import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let ynoLogoPlane: THREE.Mesh;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    let pointLight1: THREE.PointLight, pointLight2: THREE.PointLight;
    let lastMode: EmotionalMode | null = null;

    let particles: THREE.Points;
    let particleGeometry: THREE.BufferGeometry;
    let particleVelocities: Float32Array;
    const PARTICLE_COUNT = 5000;

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;
        coreMaterial: THREE.MeshStandardMaterial;
        initialPos: THREE.Vector3;
        floatOffset: number;
        floatSpeed: number;
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // For volume calculation
    const dataArray = new Uint8Array(256);

    const modeThemes: Record<EmotionalMode, { light1: number, light2: number, fog: number, particleColor: number }> = {
      Professional: { light1: 0xDA70D6, light2: 0x00ffff, fog: 0x0a0a2e, particleColor: 0xDA70D6 },
      Enthusiastic: { light1: 0xffd700, light2: 0xff4500, fog: 0x2e1a0a, particleColor: 0xffd700 },
      Cautious: { light1: 0x4682B4, light2: 0x3CB371, fog: 0x1a2e2e, particleColor: 0x4682B4 },
      Zen: { light1: 0x98FB98, light2: 0xADD8E6, fog: 0x1a1a2e, particleColor: 0x98FB98 }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            // Sci-fi chirp
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(1500, ctx.currentTime + 0.1);
            osc.frequency.exponentialRampToValueAtTime(500, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.1, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);

            osc.start();
            osc.stop(ctx.currentTime + 0.4);
        } catch (e) {
            console.warn("Audio context not available for interaction sound", e);
        }
    };

    const init = () => {
      scene = new THREE.Scene();

      if (videoRef.current) {
          const videoTexture = new THREE.VideoTexture(videoRef.current);
          scene.background = videoTexture;
      } else {
          scene.background = new THREE.Color(0x0a0a2e);
      }

      scene.fog = new THREE.Fog(0x0a0a2e, 10, 50);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.z = 15;
      camera.position.y = 0;

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 1.0);
      hemiLight.position.set(0, 50, 0);
      scene.add(hemiLight);

      const directionalLight = new THREE.DirectionalLight(0xffffff, 1.5);
      directionalLight.position.set(20, 25, 15);
      scene.add(directionalLight);

      pointLight1 = new THREE.PointLight(0xDA70D6, 3, 100);
      pointLight1.position.set(10, 5, 10);
      scene.add(pointLight1);

      pointLight2 = new THREE.PointLight(0x00ffff, 3, 100);
      pointLight2.position.set(-10, -5, 10);
      scene.add(pointLight2);

      createYnoAssets();
      createParticles();

      // Create Robots
      createRobot(-6, -2, 4);
      createRobot(6, -2, 4);
    };

    const createRobot = (x: number, y: number, z: number) => {
        const group = new THREE.Group();
        group.position.set(x, y, z);

        // Materials
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.3, 
            metalness: 0.8 
        });
        const jointMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.7, 
            metalness: 0.5 
        });
        // Initial color will be updated in animate loop
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, 
            emissive: 0x00ffff, 
            emissiveIntensity: 2 
        });

        // Torso
        const torsoGeo = new THREE.CylinderGeometry(0.5, 0.3, 1.5, 8);
        const torso = new THREE.Mesh(torsoGeo, bodyMat);
        torso.position.y = 0.75;
        group.add(torso);

        // Core (Glowing)
        const coreGeo = new THREE.OctahedronGeometry(0.2);
        const core = new THREE.Mesh(coreGeo, glowMat);
        core.position.set(0, 0.75, 0.4);
        group.add(core);

        // Head Group (for rotation)
        const headGroup = new THREE.Group();
        headGroup.position.y = 1.6;
        group.add(headGroup);

        // Head Mesh
        const headGeo = new THREE.BoxGeometry(0.6, 0.5, 0.6);
        const head = new THREE.Mesh(headGeo, bodyMat);
        headGroup.add(head);

        // Eyes (Glowing)
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.15, 0.05, 0.28);
        headGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.15, 0.05, 0.28);
        headGroup.add(rightEye);

        // Antenna
        const antennaStemGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.3);
        const antennaStem = new THREE.Mesh(antennaStemGeo, jointMat);
        antennaStem.position.set(0.2, 0.4, -0.1);
        headGroup.add(antennaStem);

        const antennaTipGeo = new THREE.SphereGeometry(0.05);
        const antennaTip = new THREE.Mesh(antennaTipGeo, glowMat);
        antennaTip.position.set(0, 0.15, 0);
        antennaStem.add(antennaTip);

        // Shoulders
        const shoulderGeo = new THREE.SphereGeometry(0.25);
        const leftShoulder = new THREE.Mesh(shoulderGeo, jointMat);
        leftShoulder.position.set(-0.6, 1.3, 0);
        group.add(leftShoulder);

        const rightShoulder = new THREE.Mesh(shoulderGeo, jointMat);
        rightShoulder.position.set(0.6, 1.3, 0);
        group.add(rightShoulder);

        // Arms (Floating)
        const armGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.8);
        const leftArm = new THREE.Mesh(armGeo, bodyMat);
        leftArm.position.set(-0.8, 0.8, 0.2);
        leftArm.rotation.z = 0.2;
        leftArm.rotation.x = -0.2;
        group.add(leftArm);

        const rightArm = new THREE.Mesh(armGeo, bodyMat);
        rightArm.position.set(0.8, 0.8, 0.2);
        rightArm.rotation.z = -0.2;
        rightArm.rotation.x = -0.2;
        group.add(rightArm);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            coreMaterial: glowMat,
            initialPos: new THREE.Vector3(x, y, z),
            floatOffset: Math.random() * Math.PI * 2,
            floatSpeed: 0.5 + Math.random() * 0.5,
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createParticles = () => {
        particleGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(PARTICLE_COUNT * 3);
        particleVelocities = new Float32Array(PARTICLE_COUNT * 3);

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const i3 = i * 3;
            positions[i3] = 0;
            positions[i3 + 1] = 1.5;
            positions[i3 + 2] = 0;

            particleVelocities[i3] = (Math.random() - 0.5) * 0.15;
            particleVelocities[i3 + 1] = (Math.random() - 0.5) * 0.15;
            particleVelocities[i3 + 2] = (Math.random() - 0.5) * 0.15;
        }

        particleGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        const particleMaterial = new THREE.PointsMaterial({
            size: 0.1,
            color: modeThemes.Professional.particleColor,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
        });

        particles = new THREE.Points(particleGeometry, particleMaterial);
        particles.position.y = -1.5;
        scene.add(particles);
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.9, 0.9, 0.9);
            ynoLogoPlane.position.set(0, 1.5, 0);
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Calculate volume
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            const sum = dataArray.reduce((a, b) => a + b, 0);
            currentVolume = sum / dataArray.length || 0;
        }

        if (currentMode !== lastMode) {
            const theme = modeThemes[currentMode];
            if (theme) {
                pointLight1.color.setHex(theme.light1);
                pointLight2.color.setHex(theme.light2);
                (scene.fog as THREE.Fog).color.setHex(theme.fog);
                if (scene.background instanceof THREE.Color) {
                    scene.background.setHex(theme.fog);
                }
                if (particles) {
                    (particles.material as THREE.PointsMaterial).color.setHex(theme.particleColor);
                }
                // Update robots
                robots.forEach(robot => {
                    robot.eyesMaterial.color.setHex(theme.particleColor);
                    robot.eyesMaterial.emissive.setHex(theme.particleColor);
                    robot.coreMaterial.color.setHex(theme.particleColor);
                    robot.coreMaterial.emissive.setHex(theme.particleColor);
                });
            }
            lastMode = currentMode;
        }

        let speedFactor = 1.0;
        switch(currentMode) {
            case 'Enthusiastic': speedFactor = 1.5; break;
            case 'Cautious': speedFactor = 0.7; break;
            case 'Zen': speedFactor = 0.4; break;
        }

        const audioInfluence = Math.min(currentVolume / 50, 1.0); // 0 to 1 range approx

        // Animate Robots
        robots.forEach(robot => {
            if (robot.isInteract) {
                const elapsed = time - robot.interactStartTime;
                const duration = 1.0;

                if (elapsed < duration) {
                    // Interaction Animation: Jump and Spin
                    const t = elapsed / duration;
                    const jumpHeight = 1.5;
                    // Sine wave for smooth jump up and down
                    const jumpY = Math.sin(t * Math.PI) * jumpHeight;

                    robot.group.position.y = robot.initialPos.y + jumpY;
                    robot.group.rotation.y += 0.25; // Fast spin

                    // Intense glowing eyes
                    robot.eyesMaterial.emissiveIntensity = 3 + Math.sin(elapsed * 20) * 2;
                } else {
                    robot.isInteract = false;
                }
            } else {
                // Standard Behavior

                // Floating
                robot.group.position.y = robot.initialPos.y + Math.sin(time * robot.floatSpeed + robot.floatOffset) * 0.3 * speedFactor;

                // Look at mouse (Body follows slightly, Head follows more)
                // Normalized mouse X is -1 to 1. 
                const targetRotationY = mouse.x * 0.5; 
                const targetRotationX = -mouse.y * 0.3;

                // Interpolate body rotation
                robot.group.rotation.y += (targetRotationY * 0.3 - robot.group.rotation.y) * 0.1;
                robot.group.rotation.x += (targetRotationX * 0.1 - robot.group.rotation.x) * 0.1;

                // Interpolate head rotation (more responsive)
                robot.headGroup.rotation.y = targetRotationY * 1.5;
                robot.headGroup.rotation.x = targetRotationX * 1.2;

                // Audio reaction
                const scale = 1 + audioInfluence * 0.15;
                robot.group.scale.set(scale, scale, scale);

                // Pulse emission
                const baseEmissive = 1.5;
                const pulse = baseEmissive + Math.sin(time * 5) * 0.5 + audioInfluence * 3;
                robot.eyesMaterial.emissiveIntensity = pulse;
            }
        });

        if (ynoLogoPlane) {
            ynoLogoPlane.position.y = 1.5 + Math.sin(time * 0.5 * speedFactor) * 0.5;
            ynoLogoPlane.rotation.y = Math.sin(time * 0.3 * speedFactor) * 0.2;

            const scale = 0.9 + audioInfluence * 0.1 + Math.sin(time * 0.7 * speedFactor) * 0.05;
            ynoLogoPlane.scale.set(scale, scale, scale);
        }

        if (particles) {
            const positions = particleGeometry.attributes.position.array as Float32Array;
            const particleSpeed = 1.0 + audioInfluence * 4.0;
            const activeParticles = Math.floor(PARTICLE_COUNT * (0.1 + audioInfluence * 0.9));

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const i3 = i * 3;

                if (i < activeParticles) {
                    positions[i3] += particleVelocities[i3] * particleSpeed;
                    positions[i3 + 1] += particleVelocities[i3 + 1] * particleSpeed;
                    positions[i3 + 2] += particleVelocities[i3 + 2] * particleSpeed;

                    const distSq = positions[i3] ** 2 + (positions[i3 + 1] - 1.5) ** 2 + positions[i3 + 2] ** 2;
                    if (distSq > 15 * 15) {
                        positions[i3] = 0;
                        positions[i3 + 1] = 1.5;
                        positions[i3 + 2] = 0;
                        particleVelocities[i3] = (Math.random() - 0.5) * 0.15;
                        particleVelocities[i3 + 1] = (Math.random() - 0.5) * 0.15;
                        particleVelocities[i3 + 2] = (Math.random() - 0.5) * 0.15;
                    }
                } else {
                     if(positions[i3] !== 0 || positions[i3 + 1] !== 1.5 || positions[i3 + 2] !== 0) {
                        positions[i3] = 0;
                        positions[i3 + 1] = 1.5;
                        positions[i3 + 2] = 0;
                    }
                }
            }
            particleGeometry.attributes.position.needsUpdate = true;
            particles.rotation.y += delta * 0.05 * speedFactor;
        }


        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.05;
        camera.position.y += (-mouse.y * 2 - camera.position.y) * 0.05;
        camera.lookAt(scene.position);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        // Only react if click is on the canvas (ignore clicks on UI buttons which stop propagation usually, but if not, check target)
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        // Raycast against robot groups. We need to check children recursively.
        // We can just check intersectObjects on the scene or specific robot groups.
        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            // Find which robot was clicked
            // intersect object will be a mesh, need to traverse up to find the group in our robots array
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
        // Dispose geometries/materials ideally
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default ThreeCanvas;

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let ynoLogoPlane: THREE.Mesh;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    let pointLight1: THREE.PointLight, pointLight2: THREE.PointLight;
    let lastMode: EmotionalMode | null = null;

    // Immersive Background Elements
    let starGeo: THREE.BufferGeometry;
    let stars: THREE.Points;
    let starVelocities: Float32Array;

    let neuralLattice: THREE.Mesh;
    let floatingMonoliths: THREE.Mesh[] = [];

    const PARTICLE_COUNT = 8000;

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;
        coreMaterial: THREE.MeshStandardMaterial;
        initialPos: THREE.Vector3;
        floatOffset: number;
        floatSpeed: number;
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // For volume calculation
    const dataArray = new Uint8Array(256);

    // Advanced Color Themes
    const modeThemes: Record<EmotionalMode, { 
        light1: number, 
        light2: number, 
        bg: number, 
        lattice: number,
        monolith: number 
    }> = {
      Professional: { light1: 0x8A2BE2, light2: 0x00FFFF, bg: 0x050510, lattice: 0x4B0082, monolith: 0x00FFFF },
      Enthusiastic: { light1: 0xFFD700, light2: 0xFF4500, bg: 0x1a0505, lattice: 0xFF8C00, monolith: 0xFFD700 },
      Cautious: { light1: 0x2E8B57, light2: 0x4682B4, bg: 0x051010, lattice: 0x006400, monolith: 0x20B2AA },
      Zen: { light1: 0xFFB6C1, light2: 0xE6E6FA, bg: 0x101015, lattice: 0x9370DB, monolith: 0xFF69B4 }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            // Sci-fi chirp
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(1500, ctx.currentTime + 0.1);
            osc.frequency.exponentialRampToValueAtTime(500, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.1, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);

            osc.start();
            osc.stop(ctx.currentTime + 0.4);
        } catch (e) {
            console.warn("Audio context not available for interaction sound", e);
        }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.02);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.z = 15;
      camera.position.y = 0;

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lighting
      const ambientLight = new THREE.AmbientLight(0x404040); // Soft white light
      scene.add(ambientLight);

      const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.8);
      hemiLight.position.set(0, 50, 0);
      scene.add(hemiLight);

      pointLight1 = new THREE.PointLight(0xDA70D6, 2, 50);
      pointLight1.position.set(10, 5, 10);
      scene.add(pointLight1);

      pointLight2 = new THREE.PointLight(0x00ffff, 2, 50);
      pointLight2.position.set(-10, -5, 10);
      scene.add(pointLight2);

      // -- IMMERSIVE BACKGROUND SETUP --
      createWarpTunnel();
      createNeuralLattice();
      createFloatingMonoliths();

      createYnoAssets();

      // Create Robots
      createRobot(-6, -2, 4);
      createRobot(6, -2, 4);
    };

    const createWarpTunnel = () => {
        starGeo = new THREE.BufferGeometry();
        const positions = new Float32Array(PARTICLE_COUNT * 3);
        starVelocities = new Float32Array(PARTICLE_COUNT);

        for(let i=0; i<PARTICLE_COUNT; i++) {
            positions[i*3] = (Math.random() - 0.5) * 100; // x
            positions[i*3+1] = (Math.random() - 0.5) * 100; // y
            positions[i*3+2] = (Math.random() - 0.5) * 100; // z
            starVelocities[i] = Math.random() * 0.2;
        }

        starGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const starMat = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.15,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });

        stars = new THREE.Points(starGeo, starMat);
        scene.add(stars);
    };

    const createNeuralLattice = () => {
        // A large Icosahedron surrounding the scene
        const geometry = new THREE.IcosahedronGeometry(30, 1);
        const wireframe = new THREE.WireframeGeometry(geometry);
        const material = new THREE.LineBasicMaterial({ 
            color: modeThemes.Professional.lattice, 
            transparent: true, 
            opacity: 0.15,
            linewidth: 1 
        });

        neuralLattice = new THREE.LineSegments(wireframe, material);
        scene.add(neuralLattice);
    };

    const createFloatingMonoliths = () => {
        const geometries = [
            new THREE.TetrahedronGeometry(1),
            new THREE.OctahedronGeometry(1),
            new THREE.DodecahedronGeometry(1)
        ];

        for (let i = 0; i < 5; i++) {
            const geo = geometries[i % geometries.length];
            const mat = new THREE.MeshPhongMaterial({
                color: modeThemes.Professional.monolith,
                transparent: true,
                opacity: 0.2,
                shininess: 100,
                side: THREE.DoubleSide,
                flatShading: true
            });
            const mesh = new THREE.Mesh(geo, mat);

            // Scatter them in the background
            mesh.position.set(
                (Math.random() - 0.5) * 40,
                (Math.random() - 0.5) * 20,
                -10 - Math.random() * 20 
            );
            mesh.scale.setScalar(2 + Math.random() * 3);

            floatingMonoliths.push(mesh);
            scene.add(mesh);
        }
    };

    const createRobot = (x: number, y: number, z: number) => {
        const group = new THREE.Group();
        group.position.set(x, y, z);

        // Materials
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.2, 
            metalness: 0.9 
        });
        const jointMat = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            roughness: 0.5, 
            metalness: 0.7 
        });
        // Initial color will be updated in animate loop
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, 
            emissive: 0x00ffff, 
            emissiveIntensity: 2 
        });

        // Torso
        const torsoGeo = new THREE.CylinderGeometry(0.5, 0.3, 1.5, 8);
        const torso = new THREE.Mesh(torsoGeo, bodyMat);
        torso.position.y = 0.75;
        group.add(torso);

        // Core (Glowing)
        const coreGeo = new THREE.OctahedronGeometry(0.2);
        const core = new THREE.Mesh(coreGeo, glowMat);
        core.position.set(0, 0.75, 0.4);
        group.add(core);

        // Head Group (for rotation)
        const headGroup = new THREE.Group();
        headGroup.position.y = 1.6;
        group.add(headGroup);

        // Head Mesh
        const headGeo = new THREE.BoxGeometry(0.6, 0.5, 0.6);
        const head = new THREE.Mesh(headGeo, bodyMat);
        headGroup.add(head);

        // Eyes (Glowing)
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.15, 0.05, 0.28);
        headGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.15, 0.05, 0.28);
        headGroup.add(rightEye);

        // Antenna
        const antennaStemGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.3);
        const antennaStem = new THREE.Mesh(antennaStemGeo, jointMat);
        antennaStem.position.set(0.2, 0.4, -0.1);
        headGroup.add(antennaStem);

        const antennaTipGeo = new THREE.SphereGeometry(0.05);
        const antennaTip = new THREE.Mesh(antennaTipGeo, glowMat);
        antennaTip.position.set(0, 0.15, 0);
        antennaStem.add(antennaTip);

        // Shoulders
        const shoulderGeo = new THREE.SphereGeometry(0.25);
        const leftShoulder = new THREE.Mesh(shoulderGeo, jointMat);
        leftShoulder.position.set(-0.6, 1.3, 0);
        group.add(leftShoulder);

        const rightShoulder = new THREE.Mesh(shoulderGeo, jointMat);
        rightShoulder.position.set(0.6, 1.3, 0);
        group.add(rightShoulder);

        // Arms (Floating)
        const armGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.8);
        const leftArm = new THREE.Mesh(armGeo, bodyMat);
        leftArm.position.set(-0.8, 0.8, 0.2);
        leftArm.rotation.z = 0.2;
        leftArm.rotation.x = -0.2;
        group.add(leftArm);

        const rightArm = new THREE.Mesh(armGeo, bodyMat);
        rightArm.position.set(0.8, 0.8, 0.2);
        rightArm.rotation.z = -0.2;
        rightArm.rotation.x = -0.2;
        group.add(rightArm);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            coreMaterial: glowMat,
            initialPos: new THREE.Vector3(x, y, z),
            floatOffset: Math.random() * Math.PI * 2,
            floatSpeed: 0.5 + Math.random() * 0.5,
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.9, 0.9, 0.9);
            ynoLogoPlane.position.set(0, 1.5, 0);
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Calculate volume
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            const sum = dataArray.reduce((a, b) => a + b, 0);
            currentVolume = sum / dataArray.length || 0;
        }

        const audioInfluence = Math.min(currentVolume / 50, 1.0); // 0 to 1 range approx

        if (currentMode !== lastMode) {
            const theme = modeThemes[currentMode];
            if (theme) {
                // Smoothly transition background color
                // scene.background = new THREE.Color(theme.bg);
                // scene.fog = new THREE.FogExp2(theme.bg, 0.02);

                // Keep lights dynamic
                pointLight1.color.setHex(theme.light1);
                pointLight2.color.setHex(theme.light2);

                // Update lattice color
                if (neuralLattice) {
                    (neuralLattice.material as THREE.LineBasicMaterial).color.setHex(theme.lattice);
                }

                // Update Monoliths
                floatingMonoliths.forEach(m => {
                    (m.material as THREE.MeshPhongMaterial).color.setHex(theme.monolith);
                });

                // Update robots
                robots.forEach(robot => {
                    robot.eyesMaterial.color.setHex(theme.monolith);
                    robot.eyesMaterial.emissive.setHex(theme.monolith);
                    robot.coreMaterial.color.setHex(theme.monolith);
                    robot.coreMaterial.emissive.setHex(theme.monolith);
                });
            }
            lastMode = currentMode;
        }

        let speedFactor = 1.0;
        switch(currentMode) {
            case 'Enthusiastic': speedFactor = 2.0; break;
            case 'Cautious': speedFactor = 0.5; break;
            case 'Zen': speedFactor = 0.2; break;
        }

        // --- ANIMATE BACKGROUND ---

        // 1. Warp Tunnel Stars
        if (stars) {
            const positions = starGeo.attributes.position.array as Float32Array;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                // Move Z towards camera
                positions[i*3 + 2] += (0.1 + starVelocities[i] * audioInfluence) * speedFactor;

                // Reset if behind camera
                if (positions[i*3 + 2] > 20) {
                    positions[i*3 + 2] = -80;
                    // Randomize X/Y again for freshness
                    positions[i*3] = (Math.random() - 0.5) * 100;
                    positions[i*3+1] = (Math.random() - 0.5) * 100;
                }
            }
            starGeo.attributes.position.needsUpdate = true;
            // Rotate the whole star tube slowly
            stars.rotation.z += 0.001 * speedFactor;
        }

        // 2. Neural Lattice
        if (neuralLattice) {
            neuralLattice.rotation.x += 0.002 * speedFactor;
            neuralLattice.rotation.y += 0.003 * speedFactor;

            // Breathing effect based on audio
            const scale = 1 + Math.sin(time * 0.5) * 0.05 + audioInfluence * 0.1;
            neuralLattice.scale.set(scale, scale, scale);
        }

        // 3. Floating Monoliths
        floatingMonoliths.forEach((m, idx) => {
            m.rotation.x += 0.01 * (idx % 2 === 0 ? 1 : -1) * speedFactor;
            m.rotation.y += 0.01 * (idx % 2 === 0 ? -1 : 1) * speedFactor;

            // Gentle float + audio kick
            m.position.y += Math.sin(time + idx) * 0.02;

            const mScale = 1 + audioInfluence * 0.5;
            m.scale.set(mScale, mScale, mScale);
        });

        // --- ANIMATE ROBOTS ---
        robots.forEach(robot => {
            if (robot.isInteract) {
                const elapsed = time - robot.interactStartTime;
                const duration = 1.0;

                if (elapsed < duration) {
                    const t = elapsed / duration;
                    const jumpHeight = 1.5;
                    const jumpY = Math.sin(t * Math.PI) * jumpHeight;

                    robot.group.position.y = robot.initialPos.y + jumpY;
                    robot.group.rotation.y += 0.25; 
                    robot.eyesMaterial.emissiveIntensity = 3 + Math.sin(elapsed * 20) * 2;
                } else {
                    robot.isInteract = false;
                }
            } else {
                robot.group.position.y = robot.initialPos.y + Math.sin(time * robot.floatSpeed + robot.floatOffset) * 0.3 * speedFactor;

                const targetRotationY = mouse.x * 0.5; 
                const targetRotationX = -mouse.y * 0.3;

                robot.group.rotation.y += (targetRotationY * 0.3 - robot.group.rotation.y) * 0.1;
                robot.group.rotation.x += (targetRotationX * 0.1 - robot.group.rotation.x) * 0.1;

                robot.headGroup.rotation.y = targetRotationY * 1.5;
                robot.headGroup.rotation.x = targetRotationX * 1.2;

                const scale = 1 + audioInfluence * 0.15;
                robot.group.scale.set(scale, scale, scale);

                const baseEmissive = 1.5;
                const pulse = baseEmissive + Math.sin(time * 5) * 0.5 + audioInfluence * 3;
                robot.eyesMaterial.emissiveIntensity = pulse;
            }
        });

        // --- ANIMATE LOGO ---
        if (ynoLogoPlane) {
            ynoLogoPlane.position.y = 1.5 + Math.sin(time * 0.5 * speedFactor) * 0.5;
            ynoLogoPlane.rotation.y = Math.sin(time * 0.3 * speedFactor) * 0.2;

            const scale = 0.9 + audioInfluence * 0.1 + Math.sin(time * 0.7 * speedFactor) * 0.05;
            ynoLogoPlane.scale.set(scale, scale, scale);
        }

        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.05;
        camera.position.y += (-mouse.y * 2 - camera.position.y) * 0.05;
        camera.lookAt(scene.position);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
        // Dispose geometries/materials ideally
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default ThreeCanvas;

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let ynoLogoPlane: THREE.Mesh;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();

    // Environment Elements
    let terrain1: THREE.Mesh, terrain2: THREE.Mesh;
    let cyberSun: THREE.Mesh;
    let floatingData: THREE.InstancedMesh;
    const DATA_COUNT = 200;

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;
        coreMaterial: THREE.MeshStandardMaterial;
        // Movement state
        targetPos: THREE.Vector3;
        velocity: THREE.Vector3;
        // Interaction state
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // Audio Data
    const dataArray = new Uint8Array(256);

    // Color Themes
    const modeThemes: Record<EmotionalMode, { 
        sky: number, 
        grid: number, 
        sun: number, 
        robot: number,
        fogDensity: number
    }> = {
      Professional: { sky: 0x050510, grid: 0x8A2BE2, sun: 0x00FFFF, robot: 0x00FFFF, fogDensity: 0.015 },
      Enthusiastic: { sky: 0x1a0a00, grid: 0xFF4500, sun: 0xFFD700, robot: 0xFFD700, fogDensity: 0.01 },
      Cautious: { sky: 0x001a0a, grid: 0x006400, sun: 0x00FF00, robot: 0x20B2AA, fogDensity: 0.02 },
      Zen: { sky: 0x101015, grid: 0xFFB6C1, sun: 0xE6E6FA, robot: 0xFF69B4, fogDensity: 0.01 }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.1);
            osc.frequency.linearRampToValueAtTime(1200, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

            osc.start();
            osc.stop(ctx.currentTime + 0.5);
        } catch (e) { console.warn(e); }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.015);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(0, 3, 10);
      camera.lookAt(0, 0, -20);

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lights
      const ambientLight = new THREE.AmbientLight(0x404040, 2);
      scene.add(ambientLight);

      const sunLight = new THREE.PointLight(0xffffff, 1, 100);
      sunLight.position.set(0, 20, -50);
      scene.add(sunLight);

      // --- ENVIRONMENT ---
      createInfiniteTerrain();
      createCyberSun();
      createFloatingData();
      createYnoAssets();

      // --- ROBOTS ---
      // Robots now start in flight
      createRobot(new THREE.Vector3(-5, 0, -5));
      createRobot(new THREE.Vector3(5, 0, -5));
    };

    // Helper to generate noisy terrain geometry
    const generateTerrainGeometry = () => {
        const geometry = new THREE.PlaneGeometry(200, 200, 40, 40);
        geometry.rotateX(-Math.PI / 2);

        const positions = geometry.attributes.position.array as Float32Array;
        // Simple pseudo-random noise for peaks
        for(let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            // const y = positions[i+1]; 
            // const z = positions[i+2]; // In rotated plane, Z is depth relative to plane normal, effectively Y world

            // Create a "Valley" in the middle (x near 0)
            const distFromCenter = Math.abs(x);
            const height = Math.sin(x * 0.1) * 2 + (Math.random() * 2);

            // Lift edges up to form a canyon
            positions[i + 1] = (distFromCenter > 10 ? height + (distFromCenter - 10) * 0.5 : height * 0.2) - 10;
        }
        geometry.computeVertexNormals();
        return geometry;
    };

    const createInfiniteTerrain = () => {
        const geometry = generateTerrainGeometry();
        const material = new THREE.MeshStandardMaterial({
            color: 0x000000,
            emissive: modeThemes.Professional.grid,
            emissiveIntensity: 0.5,
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });

        terrain1 = new THREE.Mesh(geometry, material);
        terrain1.position.z = -50;

        terrain2 = new THREE.Mesh(geometry, material);
        terrain2.position.z = -250;

        scene.add(terrain1);
        scene.add(terrain2);
    };

    const createCyberSun = () => {
        const geometry = new THREE.IcosahedronGeometry(15, 2);
        const material = new THREE.MeshBasicMaterial({
            color: modeThemes.Professional.sun,
            wireframe: true,
            transparent: true,
            opacity: 0.8
        });
        cyberSun = new THREE.Mesh(geometry, material);
        cyberSun.position.set(0, 10, -80);
        scene.add(cyberSun);

        // Add an inner glow sphere
        const glowGeo = new THREE.SphereGeometry(12, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
            color: modeThemes.Professional.sun,
            transparent: true,
            opacity: 0.3
        });
        const glow = new THREE.Mesh(glowGeo, glowMat);
        cyberSun.add(glow);
    };

    const createFloatingData = () => {
        const geometry = new THREE.BoxGeometry(0.5, 2, 0.5);
        const material = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 });
        floatingData = new THREE.InstancedMesh(geometry, material, DATA_COUNT);

        const dummy = new THREE.Object3D();
        for(let i=0; i<DATA_COUNT; i++) {
            dummy.position.set(
                (Math.random() - 0.5) * 100,
                -10 + Math.random() * 30,
                -100 + Math.random() * 100
            );
            dummy.scale.setScalar(0.5 + Math.random());
            dummy.updateMatrix();
            floatingData.setMatrixAt(i, dummy.matrix);
        }
        scene.add(floatingData);
    };

    const createRobot = (startPos: THREE.Vector3) => {
        const group = new THREE.Group();
        group.position.copy(startPos);

        // Robot styling
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, roughness: 0.2, metalness: 0.9 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2 
        });

        // Simplified, aerodynamic Robot Body for flying
        // Core
        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.5, 2, 8), bodyMat);
        torso.rotation.x = Math.PI / 2; // Point forward
        group.add(torso);

        const engine = new THREE.Mesh(new THREE.SphereGeometry(0.4), glowMat);
        engine.position.z = 1;
        group.add(engine);

        // Head Group (rotates independently)
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.3, -0.8);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), bodyMat);
        headGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.1);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.4);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.4);
        headGroup.add(rightEye);

        // Wings/Arms
        const wingGeo = new THREE.BoxGeometry(2.5, 0.1, 0.5);
        const wings = new THREE.Mesh(wingGeo, bodyMat);
        wings.position.set(0, 0, 0);
        group.add(wings);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            coreMaterial: glowMat,
            targetPos: new THREE.Vector3(
                (Math.random() - 0.5) * 20,
                (Math.random() - 0.5) * 10,
                -10 - Math.random() * 20
            ),
            velocity: new THREE.Vector3(),
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.5, 0.5, 0.5);
            ynoLogoPlane.position.set(0, 8, -40); // High up in the distance
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 50, 1.0);

        // Mode Switching
        const theme = modeThemes[currentMode];
        if (theme) {
            // Lerp fog density
            const currentFog = scene.fog as THREE.FogExp2;
            currentFog.color.setHex(theme.sky);
            currentFog.density += (theme.fogDensity - currentFog.density) * 0.05;
            scene.background = new THREE.Color(theme.sky);

            // Update Materials
            if (terrain1) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (cyberSun) {
                 (cyberSun.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
                 (cyberSun.children[0] as THREE.MeshBasicMaterial).color.setHex(theme.sun);
            }

            robots.forEach(r => {
                r.eyesMaterial.color.setHex(theme.robot);
                r.eyesMaterial.emissive.setHex(theme.robot);
            });
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 2 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence);

        // --- ANIMATION: TERRAIN SCROLL ---
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1 && terrain2) {
            terrain1.position.z += terrainSpeed;
            terrain2.position.z += terrainSpeed;

            if (terrain1.position.z > 50) terrain1.position.z = -350;
            if (terrain2.position.z > 50) terrain2.position.z = -350;
        }

        // --- ANIMATION: CYBER SUN ---
        if (cyberSun) {
            cyberSun.rotation.y += 0.005 * speedFactor;
            cyberSun.rotation.z += 0.002;
            const scale = 1 + Math.sin(time) * 0.05 + audioInfluence * 0.3;
            cyberSun.scale.set(scale, scale, scale);

            // Glitch effect on loud audio
            if (audioInfluence > 0.6) {
                cyberSun.position.x = (Math.random() - 0.5) * 0.5;
            } else {
                cyberSun.position.x = 0;
            }
        }

        // --- ANIMATION: RISING DATA ---
        if (floatingData) {
            floatingData.position.y += 0.02 * speedFactor;
            if (floatingData.position.y > 5) floatingData.position.y = 0;
            floatingData.rotation.y = time * 0.05;
        }

        // --- ANIMATION: LOGO ---
        if (ynoLogoPlane) {
            ynoLogoPlane.rotation.y = Math.sin(time * 0.5) * 0.1;
            ynoLogoPlane.position.y = 8 + Math.sin(time) * 0.5;
        }

        // --- ANIMATION: ROBOTS (FLIGHT) ---
        robots.forEach(robot => {
            if (robot.isInteract) {
                // Interaction: Flip and Spin
                const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotation.z += 0.3; // Barrel roll
                    robot.group.scale.setScalar(1.5);
                    robot.eyesMaterial.emissiveIntensity = 5;
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                    // Re-orient straight
                    robot.group.rotation.z = 0;
                }
            } else {
                // Autonomous Flight Logic
                const distToTarget = robot.group.position.distanceTo(robot.targetPos);

                if (distToTarget < 2) {
                    // Pick new target within visible frustum
                    robot.targetPos.set(
                        (Math.random() - 0.5) * 30, // X: -15 to 15
                        (Math.random() - 0.5) * 10 + 2, // Y: -3 to 7 (stay above ground)
                        -5 - Math.random() * 20 // Z: -5 to -25 (stay in front)
                    );
                }

                // Smoothly move towards target
                const direction = new THREE.Vector3().subVectors(robot.targetPos, robot.group.position).normalize();
                const flightSpeed = 5.0 * delta * speedFactor;
                robot.group.position.add(direction.multiplyScalar(flightSpeed));

                // Banking into turns
                const targetRotation = new THREE.Quaternion();
                const dummyObj = new THREE.Object3D();
                dummyObj.position.copy(robot.group.position);
                dummyObj.lookAt(robot.targetPos);
                targetRotation.copy(dummyObj.quaternion);
                robot.group.quaternion.slerp(targetRotation, 0.05);

                // Head follows mouse slightly for awareness
                robot.headGroup.rotation.y = mouse.x * 0.5;
                robot.headGroup.rotation.x = -mouse.y * 0.5;

                // Pulse
                robot.eyesMaterial.emissiveIntensity = 2 + Math.sin(time * 3) + audioInfluence * 4;
            }
        });

        // Dynamic Camera Sway
        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.02;
        camera.position.y += (3 + (-mouse.y * 1) - camera.position.y) * 0.02;
        camera.lookAt(0, 0, -20);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        // Raycast against robot groups
        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

