        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, roughness: 0.2, metalness: 0.9 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2 
        });

        // Simplified, aerodynamic Robot Body for flying
        // Core
        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.5, 2, 8), bodyMat);
        torso.rotation.x = Math.PI / 2; // Point forward
        group.add(torso);

        const engine = new THREE.Mesh(new THREE.SphereGeometry(0.4), glowMat);
        engine.position.z = 1;
        group.add(engine);

        // Head Group (rotates independently)
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.3, -0.8);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), bodyMat);
        headGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.1);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.4);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.4);
        headGroup.add(rightEye);

        // Wings/Arms
        const wingGeo = new THREE.BoxGeometry(2.5, 0.1, 0.5);
        const wings = new THREE.Mesh(wingGeo, bodyMat);
        wings.position.set(0, 0, 0);
        group.add(wings);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            coreMaterial: glowMat,
            path: path,
            progress: startProgress,
            speed: 0.1 + Math.random() * 0.05, // Base speed variation
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.5, 0.5, 0.5);
            ynoLogoPlane.position.set(0, 8, -40); // High up in the distance
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        animationId = requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 50, 1.0);

        // Mode Switching
        const theme = modeThemes[currentMode];
        if (theme) {
            // Lerp fog density
            if (scene.fog) {
                const currentFog = scene.fog as THREE.FogExp2;
                currentFog.color.setHex(theme.sky);
                currentFog.density += (theme.fogDensity - currentFog.density) * 0.05;
            }
            scene.background = new THREE.Color(theme.sky);

            // Update Materials
            if (terrain1 && terrain1.material) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2 && terrain2.material) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (cyberSun) {
                 if (cyberSun.material) (cyberSun.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
                 if (cyberSun.children[0]) {
                     const glowMesh = cyberSun.children[0] as THREE.Mesh;
                     if (glowMesh.material) {
                        (glowMesh.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
                     }
                 }
            }

            robots.forEach(r => {
                r.eyesMaterial.color.setHex(theme.robot);
                r.eyesMaterial.emissive.setHex(theme.robot);
            });
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 2 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence);

        // --- ANIMATION: TERRAIN SCROLL ---
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1 && terrain2) {
            terrain1.position.z += terrainSpeed;
            terrain2.position.z += terrainSpeed;

            if (terrain1.position.z > 50) terrain1.position.z = -350;
            if (terrain2.position.z > 50) terrain2.position.z = -350;
        }

        // --- ANIMATION: CYBER SUN ---
        if (cyberSun) {
            cyberSun.rotation.y += 0.005 * speedFactor;
            cyberSun.rotation.z += 0.002;
            const scale = 1 + Math.sin(time) * 0.05 + audioInfluence * 0.3;
            cyberSun.scale.set(scale, scale, scale);

            // Glitch effect on loud audio
            if (audioInfluence > 0.6) {
                cyberSun.position.x = (Math.random() - 0.5) * 0.5;
            } else {
                cyberSun.position.x = 0;
            }
        }

        // --- ANIMATION: RISING DATA ---
        if (floatingData) {
            floatingData.position.y += 0.02 * speedFactor;
            if (floatingData.position.y > 5) floatingData.position.y = 0;
            floatingData.rotation.y = time * 0.05;
        }

        // --- ANIMATION: LOGO ---
        if (ynoLogoPlane) {
            ynoLogoPlane.rotation.y = Math.sin(time * 0.5) * 0.1;
            ynoLogoPlane.position.y = 8 + Math.sin(time) * 0.5;
        }

        // --- ANIMATION: ROBOTS (FLIGHT ALONG PATHS) ---
        robots.forEach(robot => {
            if (robot.isInteract) {
                // Interaction: Flip and Spin
                const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotation.z += 0.3; // Barrel roll
                    robot.group.scale.setScalar(1.5);
                    robot.eyesMaterial.emissiveIntensity = 5 + (audioInfluence * 5); // Intense glow during interact
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                    // Re-orient straight
                    robot.group.rotation.z = 0;
                }
            } else {
                // FLIGHT PATH LOGIC
                // 1. Calculate new progress based on speed + audio boost
                const speedBoost = 1 + (audioInfluence * 3); // Significant boost on loud audio
                const step = (robot.speed * speedBoost * delta * speedFactor);
                robot.progress += step;
                if (robot.progress > 1) robot.progress = 0;

                // 2. Get Position on curve
                const currentPos = robot.path.getPoint(robot.progress);

                // 3. Get Look-At Target (a bit ahead on the curve)
                // Use modulo to wrap around safely
                const lookAtProgress = (robot.progress + 0.01) % 1;
                const lookAtPos = robot.path.getPoint(lookAtProgress);

                // 4. Update Position
                robot.group.position.copy(currentPos);

                // 5. Update Orientation (Look at next point)
                robot.group.lookAt(lookAtPos);

                // 6. Optional: Add banking (roll) based on curvature could go here, 
                // but lookAt + curve shape provides decent organic movement already.

                // Head follows mouse slightly for awareness while flying
                robot.headGroup.rotation.y = mouse.x * 0.5;
                robot.headGroup.rotation.x = -mouse.y * 0.5;

                // Audio Reactivity for Emission
                const pulseFrequency = 3.0 + (audioInfluence * 15.0); 
                const baseIntensity = 1.5 + (audioInfluence * 5.0);
                const sinePulse = Math.sin(time * pulseFrequency);
                const finalIntensity = baseIntensity + (sinePulse * (0.5 + audioInfluence * 2.0));
                robot.eyesMaterial.emissiveIntensity = finalIntensity;
            }
        });

        // Dynamic Camera Sway
        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.02;
        camera.position.y += (3 + (-mouse.y * 1) - camera.position.y) * 0.02;
        camera.lookAt(0, 0, -20);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        // Raycast against robot groups
        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        cancelAnimationFrame(animationId);
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default ThreeCanvas;

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

// Robot States
type RobotState = 'FLYING' | 'TRANSITION_TO_DOCK' | 'MINING' | 'TRANSITION_TO_PATH';

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    let animationId: number;

    // Environment Elements
    let terrain1: THREE.Mesh, terrain2: THREE.Mesh;
    let cyberSun: THREE.Mesh;

    // Floating Data (Burning Mechanic)
    let floatingData: THREE.InstancedMesh;
    const DATA_COUNT = 150;
    const dummy = new THREE.Object3D();
    const dataVelocities: number[] = []; // Fall speed for burning

    // Genesis Structure
    let genesisGroup: THREE.Group;
    let genesisZero: THREE.Mesh;
    let btcShell: THREE.Mesh;

    // Mining Lasers
    const laserMaterial = new THREE.LineBasicMaterial({ 
        color: 0x00ffff, 
        transparent: true, 
        opacity: 0,
        blending: THREE.AdditiveBlending 
    });

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;

        // Path State
        path: THREE.CatmullRomCurve3;
        pathProgress: number; // 0 to 1
        speed: number;

        // Complex Behavior State
        state: RobotState;
        dockPosition: THREE.Vector3; // Where it parks to mine
        transitionAlpha: number; // 0 to 1 for lerping positions
        mineTimer: number; // How long to stay docked

        // Visuals
        laserLine: THREE.Line;

        // Interaction
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // Audio Data
    const dataArray = new Uint8Array(256);

    // Color Themes
    const modeThemes: Record<EmotionalMode, { 
        sky: number, 
        grid: number, 
        sun: number, 
        robot: number,
        core: number
    }> = {
      Professional: { sky: 0x050510, grid: 0x8A2BE2, sun: 0x00FFFF, robot: 0x00FFFF, core: 0xFFFFFF },
      Enthusiastic: { sky: 0x1a0a00, grid: 0xFF4500, sun: 0xFFD700, robot: 0xFFD700, core: 0xFFA500 },
      Cautious: { sky: 0x001a0a, grid: 0x006400, sun: 0x00FF00, robot: 0x20B2AA, core: 0x00FF00 },
      Zen: { sky: 0x101015, grid: 0xFFB6C1, sun: 0xE6E6FA, robot: 0xFF69B4, core: 0xFFC0CB }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.1);
            osc.frequency.linearRampToValueAtTime(1200, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

            osc.start();
            osc.stop(ctx.currentTime + 0.5);
        } catch (e) { console.warn(e); }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.015);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(0, 5, 25); // Pulled back slightly
      camera.lookAt(0, 5, 0);

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lights
      const ambientLight = new THREE.AmbientLight(0x404040, 2);
      scene.add(ambientLight);

      const sunLight = new THREE.PointLight(0xffffff, 1, 100);
      sunLight.position.set(0, 20, -50);
      scene.add(sunLight);

      const coreLight = new THREE.PointLight(0x00ffff, 2, 30);
      coreLight.position.set(0, 8, -10);
      scene.add(coreLight);

      // --- ENVIRONMENT ---
      createInfiniteTerrain();
      createCyberSun();
      createGenesisConstruct(); // The YNO Zero inside BTC
      createFloatingData(); // Burning blocks

      // --- ROBOTS ---
      // Generate different complex paths that weave around the Genesis Construct
      const path1 = generateComplexPath(25, 12, 0); 
      const path2 = generateComplexPath(30, 15, Math.PI); 
      const path3 = generateComplexPath(20, 20, Math.PI / 2);

      createRobot(path1, 0.0);
      createRobot(path1, 0.5);
      createRobot(path2, 0.2);
      createRobot(path2, 0.7);
      createRobot(path3, 0.4);
    };

    // Helper to generate a complex, closed 3D knot/loop centered around (0,8,-10)
    const generateComplexPath = (width: number, height: number, offset: number): THREE.CatmullRomCurve3 => {
        const points: THREE.Vector3[] = [];
        const segmentCount = 12;
        const centerX = 0;
        const centerY = 8;
        const centerZ = -10;

        for (let i = 0; i < segmentCount; i++) {
            const t = (i / segmentCount) * Math.PI * 2 + offset;
            const x = centerX + Math.sin(t) * width;
            const y = centerY + Math.cos(t * 2) * (height / 2); 
            const z = centerZ + Math.cos(t) * width * 0.5;

            points.push(new THREE.Vector3(x, y, z));
        }

        return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.5);
    };

    // --- GENESIS CONSTRUCT (YNO Zero inside BTC Shell) ---
    const createGenesisConstruct = () => {
        genesisGroup = new THREE.Group();
        genesisGroup.position.set(0, 8, -10); // Central position

        // 1. The "Zero" (YNO Origin) - Dense, dark, glossy torus
        const zeroGeo = new THREE.TorusGeometry(3, 1, 16, 100);
        const zeroMat = new THREE.MeshStandardMaterial({
            color: 0x111111,
            roughness: 0.1,
            metalness: 1.0,
            emissive: modeThemes.Professional.core,
            emissiveIntensity: 0.5
        });
        genesisZero = new THREE.Mesh(zeroGeo, zeroMat);
        genesisGroup.add(genesisZero);

        // 2. The "BTC Shell" - Wireframe Icosahedron surrounding the Zero
        const shellGeo = new THREE.IcosahedronGeometry(6, 1);
        const shellMat = new THREE.MeshBasicMaterial({
            color: 0xffffff,
            wireframe: true,
            transparent: true,
            opacity: 0.15
        });
        btcShell = new THREE.Mesh(shellGeo, shellMat);
        genesisGroup.add(btcShell);

        // 3. Inner Data Particles (The "Bit" particles)
        const particleGeo = new THREE.BufferGeometry();
        const particleCount = 50;
        const positions = new Float32Array(particleCount * 3);
        for(let i=0; i<particleCount*3; i++) {
            positions[i] = (Math.random() - 0.5) * 8;
        }
        particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const particleMat = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.1,
            transparent: true,
            opacity: 0.6
        });
        const particles = new THREE.Points(particleGeo, particleMat);
        genesisGroup.add(particles);

        scene.add(genesisGroup);
    };

    // --- FLOATING DATA (BURNING MECHANIC) ---
    const createFloatingData = () => {
        const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
        const material = new THREE.MeshStandardMaterial({ 
            color: 0x888888, 
            roughness: 0.2,
            metalness: 0.8 
        });
        floatingData = new THREE.InstancedMesh(geometry, material, DATA_COUNT);
        floatingData.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        floatingData.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(DATA_COUNT * 3), 3);

        for(let i=0; i<DATA_COUNT; i++) {
            resetBlock(i);
        }
        scene.add(floatingData);
    };

    const resetBlock = (index: number) => {
        dummy.position.set(
            (Math.random() - 0.5) * 80,
            20 + Math.random() * 20, // Start high up
            -40 + Math.random() * 40
        );
        dummy.rotation.set(Math.random(), Math.random(), Math.random());
        dummy.scale.setScalar(0.5 + Math.random() * 1.5);
        dummy.updateMatrix();
        floatingData.setMatrixAt(index, dummy.matrix);

        // Set standard cool color
        const color = new THREE.Color(0x4444ff);
        floatingData.setColorAt(index, color);

        dataVelocities[index] = 0.05 + Math.random() * 0.1;
    };

    const createInfiniteTerrain = () => {
        const geometry = new THREE.PlaneGeometry(200, 200, 40, 40);
        geometry.rotateX(-Math.PI / 2);

        const positions = geometry.attributes.position.array as Float32Array;
        for(let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            const distFromCenter = Math.abs(x);
            const height = Math.sin(x * 0.1) * 2 + (Math.random() * 2);
            positions[i + 1] = (distFromCenter > 10 ? height + (distFromCenter - 10) * 0.5 : height * 0.2) - 10;
        }
        geometry.computeVertexNormals();

        const material = new THREE.MeshStandardMaterial({
            color: 0x000000,
            emissive: modeThemes.Professional.grid,
            emissiveIntensity: 0.5,
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });

        terrain1 = new THREE.Mesh(geometry, material);
        terrain1.position.z = -50;
        terrain2 = new THREE.Mesh(geometry, material);
        terrain2.position.z = -250;

        scene.add(terrain1);
        scene.add(terrain2);
    };

    const createCyberSun = () => {
        const geometry = new THREE.IcosahedronGeometry(15, 2);
        const material = new THREE.MeshBasicMaterial({
            color: modeThemes.Professional.sun,
            wireframe: true,
            transparent: true,
            opacity: 0.8
        });
        cyberSun = new THREE.Mesh(geometry, material);
        cyberSun.position.set(0, 30, -100);
        scene.add(cyberSun);
    };

    const createRobot = (path: THREE.CatmullRomCurve3, startProgress: number) => {
        const group = new THREE.Group();

        const bodyMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.2, metalness: 0.9 });
        const glowMat = new THREE.MeshStandardMaterial({ color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2 });

        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.5, 2, 8), bodyMat);
        torso.rotation.x = Math.PI / 2;
        group.add(torso);

        const engine = new THREE.Mesh(new THREE.SphereGeometry(0.4), glowMat);
        engine.position.z = 1;
        group.add(engine);

        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.3, -0.8);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), bodyMat);
        headGroup.add(head);

        const eyeGeo = new THREE.SphereGeometry(0.1);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.4);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.4);
        headGroup.add(rightEye);

        const wingGeo = new THREE.BoxGeometry(2.5, 0.1, 0.5);
        const wings = new THREE.Mesh(wingGeo, bodyMat);
        wings.position.set(0, 0, 0);
        group.add(wings);

        // Mining Laser visual
        const laserGeometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0,0), new THREE.Vector3(0,0,-5)]);
        const laserLine = new THREE.Line(laserGeometry, laserMaterial.clone());
        laserLine.visible = false;
        group.add(laserLine);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            path,
            pathProgress: startProgress,
            speed: 0.1 + Math.random() * 0.05,
            state: 'FLYING',
            dockPosition: new THREE.Vector3(),
            transitionAlpha: 0,
            mineTimer: 0,
            laserLine,
            isInteract: false,
            interactStartTime: 0
        });
    };

    const animate = () => {
        animationId = requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 50, 1.0);

        // Theme Updates
        const theme = modeThemes[currentMode];
        if (theme) {
             if (scene.fog) {
                const currentFog = scene.fog as THREE.FogExp2;
                currentFog.color.setHex(theme.sky);
                currentFog.density += (theme.fogDensity - currentFog.density) * 0.05;
            }
            scene.background = new THREE.Color(theme.sky);
            if (terrain1.material) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2.material) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (cyberSun.material) (cyberSun.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
            if (genesisZero.material) (genesisZero.material as THREE.MeshStandardMaterial).emissive.setHex(theme.core);
            robots.forEach(r => r.eyesMaterial.emissive.setHex(theme.robot));
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 2 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence);

        // --- ANIMATION: GENESIS CORE ---
        if (genesisGroup) {
            genesisZero.rotation.y += 0.01 * speedFactor; // The YNO "0" spins slowly
            btcShell.rotation.y -= 0.005; // The BTC Shell spins opposite
            btcShell.rotation.x = Math.sin(time * 0.2) * 0.2;

            // Pulse the core
            (genesisZero.material as THREE.MeshStandardMaterial).emissiveIntensity = 0.5 + Math.sin(time * 2) * 0.3 + (audioInfluence * 2);
        }

        // --- ANIMATION: BURNING DATA BLOCKS ---
        if (floatingData) {
            const matrix = new THREE.Matrix4();
            const position = new THREE.Vector3();
            const rotation = new THREE.Quaternion();
            const scale = new THREE.Vector3();
            const color = new THREE.Color();

            for (let i = 0; i < DATA_COUNT; i++) {
                floatingData.getMatrixAt(i, matrix);
                matrix.decompose(position, rotation, scale);

                // Fall down
                position.y -= dataVelocities[i] * (1 + audioInfluence * 2); // Fall faster with music

                // Burning logic: As it gets low, it turns red and shrinks
                if (position.y < 0) {
                    const burnFactor = Math.abs(position.y) / 10; // 0 to 1 as it falls to -10
                    color.setHSL(0.0 + (1-burnFactor)*0.6, 1.0, 0.5); // Blue -> Red
                    floatingData.setColorAt(i, color);
                    scale.setScalar(Math.max(0.1, 1 - burnFactor)); // Shrink
                } else {
                    // Standard State
                    floatingData.setColorAt(i, new THREE.Color(theme.grid).offsetHSL(0,0,0.2));
                }

                if (position.y < -10) {
                    resetBlock(i);
                    floatingData.setColorAt(i, new THREE.Color(theme.grid));
                } else {
                    // Recompose
                    dummy.position.copy(position);
                    dummy.quaternion.copy(rotation);
                    dummy.scale.copy(scale);
                    dummy.updateMatrix();
                    floatingData.setMatrixAt(i, dummy.matrix);
                }
            }
            floatingData.instanceMatrix.needsUpdate = true;
            if (floatingData.instanceColor) floatingData.instanceColor.needsUpdate = true;
        }

        // --- ANIMATION: ROBOTS (STATE MACHINE) ---
        robots.forEach(robot => {
            // Calculate Path Position regardless of state (ghost position)
            const speedBoost = 1 + (audioInfluence * 3);
            const step = (robot.speed * speedBoost * delta * speedFactor);
            robot.pathProgress += step;
            if (robot.pathProgress > 1) robot.pathProgress = 0;

            const pathPos = robot.path.getPoint(robot.pathProgress);
            const lookAtProgress = (robot.pathProgress + 0.01) % 1;
            const pathLookAt = robot.path.getPoint(lookAtProgress);

            if (robot.isInteract) {
                // ... (Existing interaction logic) ...
                 const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotation.z += 0.3;
                    robot.group.scale.setScalar(1.5);
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                    robot.group.rotation.z = 0;
                }
            } else {
                // STATE MACHINE
                switch (robot.state) {
                    case 'FLYING':
                        robot.group.position.copy(pathPos);
                        robot.group.lookAt(pathLookAt);

                        // Chance to start docking if near the core and not too fast
                        if (robot.group.position.distanceTo(genesisGroup.position) < 15 && Math.random() < 0.01) {
                            robot.state = 'TRANSITION_TO_DOCK';
                            robot.transitionAlpha = 0;
                            // Pick a random spot on the surface of the shell
                            const angle = Math.random() * Math.PI * 2;
                            const yOffset = (Math.random() - 0.5) * 4;
                            robot.dockPosition.set(
                                Math.sin(angle) * 7,
                                8 + yOffset,
                                -10 + Math.cos(angle) * 7
                            );
                        }
                        break;

                    case 'TRANSITION_TO_DOCK':
                        robot.transitionAlpha += delta * 1.5; // Transition speed
                        if (robot.transitionAlpha >= 1) {
                            robot.transitionAlpha = 1;
                            robot.state = 'MINING';
                            robot.mineTimer = 2.0 + Math.random() * 3.0; // Mine for 2-5 seconds
                            robot.laserLine.visible = true;
                        }
                        robot.group.position.lerpVectors(pathPos, robot.dockPosition, robot.transitionAlpha);
                        robot.group.lookAt(genesisGroup.position); // Look at the core
                        break;

                    case 'MINING':
                        // Hover/Bob
                        robot.group.position.y = robot.dockPosition.y + Math.sin(time * 5) * 0.2;
                        robot.group.lookAt(genesisGroup.position);

                        // Update Laser
                        const positions = robot.laserLine.geometry.attributes.position.array as Float32Array;
                        // Start at robot (local 0,0,0) -> End at core (local space conversion needed)
                        // Simplified: Since laser is child of robot, 0,0,0 is robot. 
                        // We need core position relative to robot.
                        const coreLocal = genesisGroup.position.clone().sub(robot.group.position);
                        positions[3] = coreLocal.x;
                        positions[4] = coreLocal.y;
                        positions[5] = coreLocal.z;
                        robot.laserLine.geometry.attributes.position.needsUpdate = true;

                        // Pulse Laser
                        (robot.laserLine.material as THREE.LineBasicMaterial).opacity = Math.random() * 0.8 + 0.2;

                        robot.mineTimer -= delta;
                        if (robot.mineTimer <= 0) {
                            robot.state = 'TRANSITION_TO_PATH';
                            robot.transitionAlpha = 0;
                            robot.laserLine.visible = false;
                        }
                        break;

                    case 'TRANSITION_TO_PATH':
                        robot.transitionAlpha += delta * 1.5;
                        if (robot.transitionAlpha >= 1) {
                            robot.state = 'FLYING';
                        }
                        robot.group.position.lerpVectors(robot.dockPosition, pathPos, robot.transitionAlpha);

                        // Smoothly rotate back to path orientation
                        const dummy = new THREE.Object3D();
                        dummy.position.copy(robot.group.position);
                        dummy.lookAt(pathLookAt);
                        robot.group.quaternion.slerp(dummy.quaternion, robot.transitionAlpha);
                        break;
                }
            }

            // Head movement
            robot.headGroup.rotation.y = mouse.x * 0.5;
            robot.headGroup.rotation.x = -mouse.y * 0.5;
        });

        // Terrain Move
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1) {
             terrain1.position.z += terrainSpeed;
             if (terrain1.position.z > 50) terrain1.position.z = -350;
        }
        if (terrain2) {
             terrain2.position.z += terrainSpeed;
             if (terrain2.position.z > 50) terrain2.position.z = -350;
        }

        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.02;
        camera.position.y += (5 + (-mouse.y * 1) - camera.position.y) * 0.02;
        camera.lookAt(0, 5, -10);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    // ... existing click handler ...
    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
        raycaster.setFromCamera(mouse, camera);
        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);
        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;
            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }
            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        cancelAnimationFrame(animationId);
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default ThreeCanvas;

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let ynoLogoPlane: THREE.Mesh;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    let animationId: number;

    // Environment Elements
    let terrain1: THREE.Mesh, terrain2: THREE.Mesh;
    let cyberSun: THREE.Mesh;
    let floatingData: THREE.InstancedMesh;
    const DATA_COUNT = 200;

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;
        coreMaterial: THREE.MeshStandardMaterial;
        // Flight Path State
        path: THREE.CatmullRomCurve3;
        progress: number; // 0 to 1
        speed: number;
        // Interaction state
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // Audio Data
    const dataArray = new Uint8Array(256);

    // Color Themes
    const modeThemes: Record<EmotionalMode, { 
        sky: number, 
        grid: number, 
        sun: number, 
        robot: number,
        fogDensity: number
    }> = {
      Professional: { sky: 0x050510, grid: 0x8A2BE2, sun: 0x00FFFF, robot: 0x00FFFF, fogDensity: 0.015 },
      Enthusiastic: { sky: 0x1a0a00, grid: 0xFF4500, sun: 0xFFD700, robot: 0xFFD700, fogDensity: 0.01 },
      Cautious: { sky: 0x001a0a, grid: 0x006400, sun: 0x00FF00, robot: 0x20B2AA, fogDensity: 0.02 },
      Zen: { sky: 0x101015, grid: 0xFFB6C1, sun: 0xE6E6FA, robot: 0xFF69B4, fogDensity: 0.01 }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.1);
            osc.frequency.linearRampToValueAtTime(1200, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

            osc.start();
            osc.stop(ctx.currentTime + 0.5);
        } catch (e) { console.warn(e); }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.015);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(0, 3, 10);
      camera.lookAt(0, 0, -20);

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lights
      const ambientLight = new THREE.AmbientLight(0x404040, 2);
      scene.add(ambientLight);

      const sunLight = new THREE.PointLight(0xffffff, 1, 100);
      sunLight.position.set(0, 20, -50);
      scene.add(sunLight);

      // --- ENVIRONMENT ---
      createInfiniteTerrain();
      createCyberSun();
      createFloatingData();
      createYnoAssets();

      // --- ROBOTS ---
      // Generate different complex paths for variety
      const path1 = generateComplexPath(20, 10); // Wide path
      const path2 = generateComplexPath(15, 15); // Taller path

      createRobot(path1, 0.0);
      createRobot(path2, 0.5); // Start halfway through the path
    };

    // Helper to generate a complex, closed 3D knot/loop
    const generateComplexPath = (width: number, height: number): THREE.CatmullRomCurve3 => {
        const points: THREE.Vector3[] = [];
        const segmentCount = 10;

        for (let i = 0; i < segmentCount; i++) {
            const t = (i / segmentCount) * Math.PI * 2;
            // Lissajous-like curve for organic sci-fi movement
            const x = Math.sin(t) * width + Math.sin(t * 3) * 5;
            const y = Math.cos(t * 2) * (height / 2) + 2; // Keep slightly above ground
            const z = Math.cos(t) * 15 - 20; // Keep in front of camera mostly

            points.push(new THREE.Vector3(x, y, z));
        }

        return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.5);
    };

    // Helper to generate noisy terrain geometry
    const generateTerrainGeometry = () => {
        const geometry = new THREE.PlaneGeometry(200, 200, 40, 40);
        geometry.rotateX(-Math.PI / 2);

        const positions = geometry.attributes.position.array as Float32Array;
        // Simple pseudo-random noise for peaks
        for(let i = 0; i < positions.length; i += 3) {
            const x = positions[i];

            // Create a "Valley" in the middle (x near 0)
            const distFromCenter = Math.abs(x);
            const height = Math.sin(x * 0.1) * 2 + (Math.random() * 2);

            // Lift edges up to form a canyon
            positions[i + 1] = (distFromCenter > 10 ? height + (distFromCenter - 10) * 0.5 : height * 0.2) - 10;
        }
        geometry.computeVertexNormals();
        return geometry;
    };

    const createInfiniteTerrain = () => {
        const geometry = generateTerrainGeometry();
        const material = new THREE.MeshStandardMaterial({
            color: 0x000000,
            emissive: modeThemes.Professional.grid,
            emissiveIntensity: 0.5,
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });

        terrain1 = new THREE.Mesh(geometry, material);
        terrain1.position.z = -50;

        terrain2 = new THREE.Mesh(geometry, material);
        terrain2.position.z = -250;

        scene.add(terrain1);
        scene.add(terrain2);
    };

    const createCyberSun = () => {
        const geometry = new THREE.IcosahedronGeometry(15, 2);
        const material = new THREE.MeshBasicMaterial({
            color: modeThemes.Professional.sun,
            wireframe: true,
            transparent: true,
            opacity: 0.8
        });
        cyberSun = new THREE.Mesh(geometry, material);
        cyberSun.position.set(0, 10, -80);
        scene.add(cyberSun);

        // Add an inner glow sphere
        const glowGeo = new THREE.SphereGeometry(12, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
            color: modeThemes.Professional.sun,
            transparent: true,
            opacity: 0.3
        });
        const glow = new THREE.Mesh(glowGeo, glowMat);
        cyberSun.add(glow);
    };

    const createFloatingData = () => {
        const geometry = new THREE.BoxGeometry(0.5, 2, 0.5);
        const material = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 });
        floatingData = new THREE.InstancedMesh(geometry, material, DATA_COUNT);

        const dummy = new THREE.Object3D();
        for(let i=0; i<DATA_COUNT; i++) {
            dummy.position.set(
                (Math.random() - 0.5) * 100,
                -10 + Math.random() * 30,
                -100 + Math.random() * 100
            );
            dummy.scale.setScalar(0.5 + Math.random());
            dummy.updateMatrix();
            floatingData.setMatrixAt(i, dummy.matrix);
        }
        scene.add(floatingData);
    };

    const createRobot = (path: THREE.CatmullRomCurve3, startProgress: number) => {
        const group = new THREE.Group();

        // Robot styling
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, roughness: 0.2, metalness: 0.9 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2 
        });

        // Simplified, aerodynamic Robot Body for flying
        // Core
        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.5, 2, 8), bodyMat);
        torso.rotation.x = Math.PI / 2; // Point forward
        group.add(torso);

        const engine = new THREE.Mesh(new THREE.SphereGeometry(0.4), glowMat);
        engine.position.z = 1;
        group.add(engine);

        // Head Group (rotates independently)
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.3, -0.8);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), bodyMat);
        headGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.1);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.4);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.4);
        headGroup.add(rightEye);

        // Wings/Arms
        const wingGeo = new THREE.BoxGeometry(2.5, 0.1, 0.5);
        const wings = new THREE.Mesh(wingGeo, bodyMat);
        wings.position.set(0, 0, 0);
        group.add(wings);

        scene.add(group);

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            coreMaterial: glowMat,
            path: path,
            progress: startProgress,
            speed: 0.1 + Math.random() * 0.05, // Base speed variation
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.5, 0.5, 0.5);
            ynoLogoPlane.position.set(0, 8, -40); // High up in the distance
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        animationId = requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 50, 1.0);

        // Mode Switching
        const theme = modeThemes[currentMode];
        if (theme) {
            // Lerp fog density
            if (scene.fog) {
                const currentFog = scene.fog as THREE.FogExp2;
                currentFog.color.setHex(theme.sky);
                currentFog.density += (theme.fogDensity - currentFog.density) * 0.05;
            }
            scene.background = new THREE.Color(theme.sky);

            // Update Materials
            if (terrain1 && terrain1.material) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2 && terrain2.material) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (cyberSun) {
                 if (cyberSun.material) (cyberSun.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
                 if (cyberSun.children[0]) {
                     const glowMesh = cyberSun.children[0] as THREE.Mesh;
                     if (glowMesh.material) {
                        (glowMesh.material as THREE.MeshBasicMaterial).color.setHex(theme.sun);
                     }
                 }
            }

            robots.forEach(r => {
                r.eyesMaterial.color.setHex(theme.robot);
                r.eyesMaterial.emissive.setHex(theme.robot);
            });
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 2 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence);

        // --- ANIMATION: TERRAIN SCROLL ---
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1 && terrain2) {
            terrain1.position.z += terrainSpeed;
            terrain2.position.z += terrainSpeed;

            if (terrain1.position.z > 50) terrain1.position.z = -350;
            if (terrain2.position.z > 50) terrain2.position.z = -350;
        }

        // --- ANIMATION: CYBER SUN ---
        if (cyberSun) {
            cyberSun.rotation.y += 0.005 * speedFactor;
            cyberSun.rotation.z += 0.002;
            const scale = 1 + Math.sin(time) * 0.05 + audioInfluence * 0.3;
            cyberSun.scale.set(scale, scale, scale);

            // Glitch effect on loud audio
            if (audioInfluence > 0.6) {
                cyberSun.position.x = (Math.random() - 0.5) * 0.5;
            } else {
                cyberSun.position.x = 0;
            }
        }

        // --- ANIMATION: RISING DATA ---
        if (floatingData) {
            floatingData.position.y += 0.02 * speedFactor;
            if (floatingData.position.y > 5) floatingData.position.y = 0;
            floatingData.rotation.y = time * 0.05;
        }

        // --- ANIMATION: LOGO ---
        if (ynoLogoPlane) {
            ynoLogoPlane.rotation.y = Math.sin(time * 0.5) * 0.1;
            ynoLogoPlane.position.y = 8 + Math.sin(time) * 0.5;
        }

        // --- ANIMATION: ROBOTS (FLIGHT ALONG PATHS) ---
        robots.forEach(robot => {
            if (robot.isInteract) {
                // Interaction: Flip and Spin
                const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotation.z += 0.3; // Barrel roll
                    robot.group.scale.setScalar(1.5);
                    robot.eyesMaterial.emissiveIntensity = 5 + (audioInfluence * 5); // Intense glow during interact
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                    // Re-orient straight
                    robot.group.rotation.z = 0;
                }
            } else {
                // FLIGHT PATH LOGIC
                // 1. Calculate new progress based on speed + audio boost
                const speedBoost = 1 + (audioInfluence * 3); // Significant boost on loud audio
                const step = (robot.speed * speedBoost * delta * speedFactor);
                robot.progress += step;
                if (robot.progress > 1) robot.progress = 0;

                // 2. Get Position on curve
                const currentPos = robot.path.getPoint(robot.progress);

                // 3. Get Look-At Target (a bit ahead on the curve)
                // Use modulo to wrap around safely
                const lookAtProgress = (robot.progress + 0.01) % 1;
                const lookAtPos = robot.path.getPoint(lookAtProgress);

                // 4. Update Position
                robot.group.position.copy(currentPos);

                // 5. Update Orientation (Look at next point)
                robot.group.lookAt(lookAtPos);

                // 6. Optional: Add banking (roll) based on curvature could go here, 
                // but lookAt + curve shape provides decent organic movement already.

                // Head follows mouse slightly for awareness while flying
                robot.headGroup.rotation.y = mouse.x * 0.5;
                robot.headGroup.rotation.x = -mouse.y * 0.5;

                // Audio Reactivity for Emission
                const pulseFrequency = 3.0 + (audioInfluence * 15.0); 
                const baseIntensity = 1.5 + (audioInfluence * 5.0);
                const sinePulse = Math.sin(time * pulseFrequency);
                const finalIntensity = baseIntensity + (sinePulse * (0.5 + audioInfluence * 2.0));
                robot.eyesMaterial.emissiveIntensity = finalIntensity;
            }
        });

        // Dynamic Camera Sway
        camera.position.x += (mouse.x * 2 - camera.position.x) * 0.02;
        camera.position.y += (3 + (-mouse.y * 1) - camera.position.y) * 0.02;
        camera.lookAt(0, 0, -20);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        // Raycast against robot groups
        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        cancelAnimationFrame(animationId);
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

