    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;

        // Flight Path State
        path: THREE.CatmullRomCurve3;
        progress: number; // 0 to 1
        speed: number;

        // "Glob" Trail State
        trailGlobs: THREE.Mesh[]; // Array of spheres following the engine

        // Laser Tool
        laserMesh: THREE.Mesh;
        isFiring: boolean;

        // Interaction state
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // Audio Data
    const dataArray = new Uint8Array(256);

    // Color Themes
    const modeThemes: Record<EmotionalMode, { 
        sky: number, 
        grid: number, 
        core: number, 
        robot: number,
        laser: number
    }> = {
      Professional: { sky: 0x050510, grid: 0x8A2BE2, core: 0x00FFFF, robot: 0x00FFFF, laser: 0x00FFFF },
      Enthusiastic: { sky: 0x1a0a00, grid: 0xFF4500, core: 0xFFD700, robot: 0xFFD700, laser: 0xFF0000 },
      Cautious: { sky: 0x001a0a, grid: 0x006400, core: 0x00FF00, robot: 0x20B2AA, laser: 0x00FF00 },
      Zen: { sky: 0x101015, grid: 0xFFB6C1, core: 0xE6E6FA, robot: 0xFF69B4, laser: 0xFFC0CB }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.1);
            osc.frequency.linearRampToValueAtTime(1200, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

            osc.start();
            osc.stop(ctx.currentTime + 0.5);
        } catch (e) { console.warn(e); }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.015);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(0, 5, 20); // Closer for clarity
      camera.lookAt(0, 5, -20);

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lights
      const ambientLight = new THREE.AmbientLight(0x404040, 2);
      scene.add(ambientLight);

      const coreLight = new THREE.PointLight(0xffffff, 1.5, 100);
      coreLight.position.set(0, 15, -60);
      scene.add(coreLight);

      // --- ENVIRONMENT ---
      createStarfield();
      createInfiniteTerrain();
      createApeirogon(); // The new Infinite Sides structure
      createMolecules(); // Ecosystem particles
      createYnoAssets();

      // --- ROBOTS ---
      // EXACTLY 2 BOTS
      const path1 = generateComplexPath(25, 10, 0); 
      const path2 = generateComplexPath(30, 20, Math.PI);

      createRobot(path1, 0.0);
      createRobot(path2, 0.5);
    };

    const createStarfield = () => {
        const geometry = new THREE.BufferGeometry();
        const count = 2000;
        const positions = new Float32Array(count * 3);

        for(let i = 0; i < count; i++) {
            positions[i * 3] = (Math.random() - 0.5) * 400;
            positions[i * 3 + 1] = (Math.random() - 0.5) * 200 + 50;
            positions[i * 3 + 2] = (Math.random() - 0.5) * 400 - 100;
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const material = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.5,
            transparent: true,
            opacity: 0.8,
            sizeAttenuation: true
        });

        stars = new THREE.Points(geometry, material);
        scene.add(stars);
    };

    const generateComplexPath = (width: number, height: number, offset: number): THREE.CatmullRomCurve3 => {
        const points: THREE.Vector3[] = [];
        const segmentCount = 12;

        for (let i = 0; i < segmentCount; i++) {
            const t = (i / segmentCount) * Math.PI * 2 + offset;
            const x = Math.sin(t) * width + Math.sin(t * 3) * 5;
            const y = Math.cos(t * 2) * (height / 2) + 5; 
            const z = Math.cos(t) * 20 - 40; // Center around the Apeirogon

            points.push(new THREE.Vector3(x, y, z));
        }

        return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.5);
    };

    const generateTerrainGeometry = () => {
        const geometry = new THREE.PlaneGeometry(300, 300, 60, 60);
        geometry.rotateX(-Math.PI / 2);

        const positions = geometry.attributes.position.array as Float32Array;
        for(let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            const distFromCenter = Math.abs(x);
            // More organic terrain
            const height = Math.sin(x * 0.1) * 3 + Math.cos(x * 0.5) * 1 + (Math.random() * 2);
            positions[i + 1] = (distFromCenter > 20 ? height + (distFromCenter - 20) * 0.8 : height * 0.1) - 20;
        }
        geometry.computeVertexNormals();
        return geometry;
    };

    const createInfiniteTerrain = () => {
        const geometry = generateTerrainGeometry();
        const material = new THREE.MeshStandardMaterial({
            color: 0x000000,
            emissive: modeThemes.Professional.grid,
            emissiveIntensity: 0.4,
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });

        terrain1 = new THREE.Mesh(geometry, material);
        terrain1.position.z = -50;

        terrain2 = new THREE.Mesh(geometry, material);
        terrain2.position.z = -350;

        scene.add(terrain1);
        scene.add(terrain2);
    };

    const createApeirogon = () => {
        apeirogonGroup = new THREE.Group();
        apeirogonGroup.position.set(0, 15, -60);
        scene.add(apeirogonGroup);

        // 1. The Core (Infinite Facets representation via high-poly sphere)
        const coreGeo = new THREE.SphereGeometry(10, 64, 64);
        const coreMat = new THREE.MeshStandardMaterial({
            color: 0x111111,
            metalness: 0.9,
            roughness: 0.1,
            emissive: modeThemes.Professional.core,
            emissiveIntensity: 0.5
        });
        const core = new THREE.Mesh(coreGeo, coreMat);
        apeirogonGroup.add(core);

        // 2. The Outer Lattice (Geometric complexity)
        const latticeGeo = new THREE.IcosahedronGeometry(14, 2);
        const latticeMat = new THREE.MeshBasicMaterial({
            color: 0xffffff,
            wireframe: true,
            transparent: true,
            opacity: 0.1
        });
        const lattice = new THREE.Mesh(latticeGeo, latticeMat);
        apeirogonGroup.add(lattice);

        // 3. Rotating Rings (The Ecosystem Power)
        const ringGeo = new THREE.TorusGeometry(18, 0.2, 16, 100);
        const ringMat = new THREE.MeshBasicMaterial({ color: modeThemes.Professional.core, transparent: true, opacity: 0.4 });

        const ring1 = new THREE.Mesh(ringGeo, ringMat);
        ring1.rotation.x = Math.PI / 2;
        apeirogonGroup.add(ring1);

        const ring2 = ring1.clone();
        ring2.rotation.x = Math.PI / 2.5;
        ring2.rotation.y = Math.PI / 6;
        apeirogonGroup.add(ring2);

        const ring3 = ring1.clone();
        ring3.rotation.x = Math.PI / 1.8;
        ring3.rotation.y = -Math.PI / 6;
        apeirogonGroup.add(ring3);
    };

    const createMolecules = () => {
        // Instanced mesh for small particles orbiting the Apeirogon
        const geometry = new THREE.OctahedronGeometry(0.5, 0);
        const material = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            emissive: 0xffffff,
            emissiveIntensity: 0.5,
            transparent: true,
            opacity: 0.6 
        });
        molecules = new THREE.InstancedMesh(geometry, material, MOLECULE_COUNT);

        const dummy = new THREE.Object3D();
        for(let i=0; i<MOLECULE_COUNT; i++) {
            // Distribute in a spherical cloud
            const r = 25 + Math.random() * 20;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);

            dummy.position.set(
                r * Math.sin(phi) * Math.cos(theta),
                15 + r * Math.sin(phi) * Math.sin(theta),
                -60 + r * Math.cos(phi)
            );
            dummy.rotation.set(Math.random()*Math.PI, Math.random()*Math.PI, 0);
            dummy.scale.setScalar(0.5 + Math.random());
            dummy.updateMatrix();
            molecules.setMatrixAt(i, dummy.matrix);
        }
        scene.add(molecules);
    };

    const createRobot = (path: THREE.CatmullRomCurve3, startProgress: number) => {
        const group = new THREE.Group();

        // --- IMPROVED BOT CLARITY & GEOMETRY ---
        // Sleeker, more distinct parts
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x050505, roughness: 0.1, metalness: 1.0 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 3 
        });
        const chromeMat = new THREE.MeshStandardMaterial({
            color: 0xaaaaaa, roughness: 0.0, metalness: 1.0
        });

        // 1. Main Fuselage
        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.8, 3.5, 6), bodyMat);
        torso.rotation.x = Math.PI / 2; 
        group.add(torso);

        // 2. Engine Core (The "Glob" source)
        const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.6, 0.5, 8), chromeMat);
        engine.rotation.x = Math.PI / 2;
        engine.position.z = 1.8;
        group.add(engine);

        const engineGlow = new THREE.Mesh(new THREE.SphereGeometry(0.35), glowMat);
        engineGlow.position.z = 2.0;
        group.add(engineGlow);

        // 3. Distinct Head
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.5, -1.0);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), chromeMat);
        headGroup.add(head);

        // 4. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.12);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.41);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.41);
        headGroup.add(rightEye);

        // 5. Wings (Sharper, clearer)
        const wingShape = new THREE.Shape();
        wingShape.moveTo(0, 0);
        wingShape.lineTo(2.5, 1.5);
        wingShape.lineTo(1.5, 2.0);
        wingShape.lineTo(0, 0.5);
        const wingGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.1, bevelEnabled: false });
        const leftWing = new THREE.Mesh(wingGeo, bodyMat);
        leftWing.rotation.x = Math.PI / 2;
        leftWing.rotation.y = 0.2;
        leftWing.position.set(0.2, 0, 0);
        group.add(leftWing);

        const rightWing = new THREE.Mesh(wingGeo, bodyMat);
        rightWing.rotation.x = Math.PI / 2;
        rightWing.rotation.y = Math.PI - 0.2;
        rightWing.rotation.z = Math.PI; // Flip for symmetry
        rightWing.position.set(-0.2, 0, 0);
        group.add(rightWing);

        scene.add(group);

        // --- GLOB TRAIL SETUP ---
        // Instead of a line, we create a series of spheres that follow the bot
        const trailGlobs: THREE.Mesh[] = [];
        const globCount = 15;
        const globMat = new THREE.MeshBasicMaterial({
            color: 0x00ffff,
            transparent: true,
            opacity: 0.6
        });

        for(let i=0; i<globCount; i++) {
            const scale = 1.0 - (i / globCount);
            const glob = new THREE.Mesh(new THREE.SphereGeometry(0.4 * scale), globMat);
            glob.visible = false; // Initially hidden until positioned
            scene.add(glob);
            trailGlobs.push(glob);
        }

        // --- LASER TOOL SETUP ---
        // A long cylinder that can stretch
        const laserGeo = new THREE.CylinderGeometry(0.05, 0.1, 1, 8);
        laserGeo.translate(0, 0.5, 0); // Pivot at bottom
        laserGeo.rotateX(Math.PI / 2); // Point forward along Z
        const laserMat = new THREE.MeshBasicMaterial({
            color: 0x00ffff,
            transparent: true,
            opacity: 0,
            blending: THREE.AdditiveBlending
        });
        const laserMesh = new THREE.Mesh(laserGeo, laserMat);
        group.add(laserMesh); // Attached to robot

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            path: path,
            progress: startProgress,
            speed: 0.1,
            trailGlobs,
            laserMesh,
            isFiring: false,
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.5, 0.5, 0.5);
            ynoLogoPlane.position.set(0, 25, -60); // Above the Apeirogon
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        animationId = requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 80, 1.0); // Normalized 0-1

        // Mode Switching Colors
        const theme = modeThemes[currentMode];
        if (theme) {
            if (scene.fog) {
                const currentFog = scene.fog as THREE.FogExp2;
                currentFog.color.setHex(theme.sky);
                currentFog.density += (theme.sky === 0x1a0a00 ? 0.01 : 0.015 - currentFog.density) * 0.05;
            }
            scene.background = new THREE.Color(theme.sky);

            if (terrain1.material) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2.material) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);

            // Apeirogon Theme
            if (apeirogonGroup) {
                const core = apeirogonGroup.children[0] as THREE.Mesh;
                if (core.material) (core.material as THREE.MeshStandardMaterial).emissive.setHex(theme.core);
                const rings = apeirogonGroup.children.slice(2);
                rings.forEach(r => (r as THREE.Mesh).material && ((r as THREE.Mesh).material as THREE.MeshBasicMaterial).color.setHex(theme.core));
            }

            robots.forEach(r => {
                r.eyesMaterial.color.setHex(theme.robot);
                r.eyesMaterial.emissive.setHex(theme.robot);
                r.trailGlobs.forEach(g => (g.material as THREE.MeshBasicMaterial).color.setHex(theme.robot));
                (r.laserMesh.material as THREE.MeshBasicMaterial).color.setHex(theme.laser);
            });
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 1.5 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence * 0.5);

        // --- ANIMATION: TERRAIN SCROLL ---
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1 && terrain2) {
            terrain1.position.z += terrainSpeed;
            terrain2.position.z += terrainSpeed;

            if (terrain1.position.z > 50) terrain1.position.z = -550;
            if (terrain2.position.z > 50) terrain2.position.z = -550;
        }

        // --- ANIMATION: APEIROGON (Infinite Sides) ---
        if (apeirogonGroup) {
            // Complex rotation
            apeirogonGroup.rotation.y += 0.005 * speedFactor;

            // Pulse the core based on audio
            const core = apeirogonGroup.children[0] as THREE.Mesh;
            const pulse = 1 + audioInfluence * 0.5;
            core.scale.setScalar(pulse);

            // Rings spin
            apeirogonGroup.children[2].rotation.z += 0.02 * speedFactor;
            apeirogonGroup.children[3].rotation.x += 0.02 * speedFactor;
        }

        // --- ANIMATION: MOLECULES ---
        if (molecules) {
            molecules.rotation.y -= 0.01 * speedFactor;
            molecules.rotation.z = Math.sin(time * 0.2) * 0.1;
        }

        // --- ANIMATION: ROBOTS ---
        robots.forEach(robot => {
            // Path Movement
            const step = (robot.speed * delta * speedFactor);
            robot.progress += step;
            if (robot.progress > 1) robot.progress = 0;

            const currentPos = robot.path.getPoint(robot.progress);
            const lookAtProgress = (robot.progress + 0.02) % 1;
            const lookAtPos = robot.path.getPoint(lookAtProgress);

            robot.group.position.copy(currentPos);
            robot.group.lookAt(lookAtPos);

            // Banking
            const tangent = new THREE.Vector3().subVectors(lookAtPos, currentPos).normalize();
            const roll = -tangent.x * 2.0; 
            robot.group.rotation.z = roll;

            // --- GLOB TRAILS ---
            // Update glob positions: Each glob lerps to the one before it
            const engineWorldPos = new THREE.Vector3(0, 0, 2.0);
            engineWorldPos.applyMatrix4(robot.group.matrixWorld);

            // The first glob follows the engine directly
            if (robot.trailGlobs.length > 0) {
                robot.trailGlobs[0].visible = true;
                robot.trailGlobs[0].position.lerp(engineWorldPos, 0.5);

                for(let i=1; i < robot.trailGlobs.length; i++) {
                    const prevGlob = robot.trailGlobs[i-1];
                    const currGlob = robot.trailGlobs[i];
                    currGlob.visible = true;
                    // Follow previous glob
                    currGlob.position.lerp(prevGlob.position, 0.4); 
                }
            }

            // --- LASER TOOL ALGO ---
            // Fire when audio is high ("Power of the Ecosystem")
            const shouldFire = audioInfluence > 0.6; // Threshold for laser

            if (shouldFire) {
                // Calculate distance and direction to Apeirogon Core
                const corePos = apeirogonGroup.position.clone();
                // We need the laser to point from the robot (local origin) to the core (world pos)
                // Since laser is child of robot, we need corePos in robot's local space
                const coreLocal = corePos.clone().applyMatrix4(robot.group.matrixWorld.clone().invert());

                // Point laser at local core coord
                robot.laserMesh.lookAt(coreLocal);

                // Scale length to distance
                const dist = robot.group.position.distanceTo(corePos);
                robot.laserMesh.scale.z = dist; // Stretch cylinder along Z

                (robot.laserMesh.material as THREE.MeshBasicMaterial).opacity = 0.5 + Math.random() * 0.5;
            } else {
                (robot.laserMesh.material as THREE.MeshBasicMaterial).opacity = 0;
            }

            // Interaction
            if (robot.isInteract) {
                const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotateZ(0.2);
                    robot.group.scale.setScalar(1.5);
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                }
            }

            // Head tracking mouse slightly
            robot.headGroup.rotation.y = mouse.x * 0.5;
            robot.headGroup.rotation.x = -mouse.y * 0.5;
        });

        // Camera Sway
        camera.position.x += (mouse.x * 3 - camera.position.x) * 0.02;
        camera.position.y += (5 + (-mouse.y * 2) - camera.position.y) * 0.02;
        camera.lookAt(0, 5, -60);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        cancelAnimationFrame(animationId);
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

export default ThreeCanvas;

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import type { EmotionalMode } from '../types';

interface ThreeCanvasProps {
  analyser: React.MutableRefObject<AnalyserNode | null>;
  videoRef: React.RefObject<HTMLVideoElement>;
  emotionalMode: EmotionalMode;
}

const ThreeCanvas: React.FC<ThreeCanvasProps> = ({ analyser, videoRef, emotionalMode }) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const stateRef = useRef({ emotionalMode });

  useEffect(() => {
    stateRef.current = { emotionalMode };
  }, [emotionalMode]);

  useEffect(() => {
    if (!mountRef.current) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let ynoLogoPlane: THREE.Mesh;
    const clock = new THREE.Clock();
    let mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    let animationId: number;

    // Environment Elements
    let terrain1: THREE.Mesh, terrain2: THREE.Mesh;
    let apeirogonGroup: THREE.Group;
    let stars: THREE.Points;
    let molecules: THREE.InstancedMesh;

    // New Particle System for Apeirogon
    let coreParticles: THREE.Points;
    let particleVelocities: Float32Array;

    const MOLECULE_COUNT = 300;

    // Robot definitions
    interface Robot {
        group: THREE.Group;
        headGroup: THREE.Group;
        eyesMaterial: THREE.MeshStandardMaterial;

        // Flight Path State
        path: THREE.CatmullRomCurve3;
        progress: number; // 0 to 1
        speed: number;

        // "Glob" Trail State
        trailGlobs: THREE.Mesh[]; // Array of spheres following the engine

        // Laser Tool
        laserMesh: THREE.Mesh;
        isFiring: boolean;

        // Interaction state
        isInteract: boolean;
        interactStartTime: number;
    }
    let robots: Robot[] = [];

    // Audio Data
    const dataArray = new Uint8Array(256);

    // Color Themes
    const modeThemes: Record<EmotionalMode, { 
        sky: number, 
        grid: number, 
        core: number, 
        robot: number,
        laser: number
    }> = {
      Professional: { sky: 0x050510, grid: 0x8A2BE2, core: 0x00FFFF, robot: 0x00FFFF, laser: 0x00FFFF },
      Enthusiastic: { sky: 0x1a0a00, grid: 0xFF4500, core: 0xFFD700, robot: 0xFFD700, laser: 0xFF0000 },
      Cautious: { sky: 0x001a0a, grid: 0x006400, core: 0x00FF00, robot: 0x20B2AA, laser: 0x00FF00 },
      Zen: { sky: 0x101015, grid: 0xFFB6C1, core: 0xE6E6FA, robot: 0xFF69B4, laser: 0xFFC0CB }
    };

    const playInteractionSound = () => {
        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const ctx = new AudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.1);
            osc.frequency.linearRampToValueAtTime(1200, ctx.currentTime + 0.3);

            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);

            osc.start();
            osc.stop(ctx.currentTime + 0.5);
        } catch (e) { console.warn(e); }
    };

    const init = () => {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x050510);
      scene.fog = new THREE.FogExp2(0x050510, 0.015);

      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(0, 5, 20); // Closer for clarity
      camera.lookAt(0, 5, -20);

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.shadowMap.enabled = true;
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Lights
      const ambientLight = new THREE.AmbientLight(0x404040, 2);
      scene.add(ambientLight);

      const coreLight = new THREE.PointLight(0xffffff, 1.5, 100);
      coreLight.position.set(0, 15, -60);
      scene.add(coreLight);

      // --- ENVIRONMENT ---
      createStarfield();
      createInfiniteTerrain();
      createApeirogon(); // The new Infinite Sides structure
      createCoreParticles(); // NEW: Particles emanating from Apeirogon
      createMolecules(); // Ecosystem particles
      createYnoAssets();

      // --- ROBOTS ---
      // EXACTLY 2 BOTS
      const path1 = generateComplexPath(25, 10, 0); 
      const path2 = generateComplexPath(30, 20, Math.PI);

      createRobot(path1, 0.0);
      createRobot(path2, 0.5);
    };

    const createStarfield = () => {
        const geometry = new THREE.BufferGeometry();
        const count = 2000;
        const positions = new Float32Array(count * 3);

        for(let i = 0; i < count; i++) {
            positions[i * 3] = (Math.random() - 0.5) * 400;
            positions[i * 3 + 1] = (Math.random() - 0.5) * 200 + 50;
            positions[i * 3 + 2] = (Math.random() - 0.5) * 400 - 100;
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const material = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.5,
            transparent: true,
            opacity: 0.8,
            sizeAttenuation: true
        });

        stars = new THREE.Points(geometry, material);
        scene.add(stars);
    };

    const generateComplexPath = (width: number, height: number, offset: number): THREE.CatmullRomCurve3 => {
        const points: THREE.Vector3[] = [];
        const segmentCount = 12;

        for (let i = 0; i < segmentCount; i++) {
            const t = (i / segmentCount) * Math.PI * 2 + offset;
            const x = Math.sin(t) * width + Math.sin(t * 3) * 5;
            const y = Math.cos(t * 2) * (height / 2) + 5; 
            const z = Math.cos(t) * 20 - 40; // Center around the Apeirogon

            points.push(new THREE.Vector3(x, y, z));
        }

        return new THREE.CatmullRomCurve3(points, true, 'catmullrom', 0.5);
    };

    const generateTerrainGeometry = () => {
        const geometry = new THREE.PlaneGeometry(300, 300, 60, 60);
        geometry.rotateX(-Math.PI / 2);

        const positions = geometry.attributes.position.array as Float32Array;
        for(let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            const distFromCenter = Math.abs(x);
            // More organic terrain
            const height = Math.sin(x * 0.1) * 3 + Math.cos(x * 0.5) * 1 + (Math.random() * 2);
            positions[i + 1] = (distFromCenter > 20 ? height + (distFromCenter - 20) * 0.8 : height * 0.1) - 20;
        }
        geometry.computeVertexNormals();
        return geometry;
    };

    const createInfiniteTerrain = () => {
        const geometry = generateTerrainGeometry();
        const material = new THREE.MeshStandardMaterial({
            color: 0x000000,
            emissive: modeThemes.Professional.grid,
            emissiveIntensity: 0.4,
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });

        terrain1 = new THREE.Mesh(geometry, material);
        terrain1.position.z = -50;

        terrain2 = new THREE.Mesh(geometry, material);
        terrain2.position.z = -350;

        scene.add(terrain1);
        scene.add(terrain2);
    };

    const createApeirogon = () => {
        apeirogonGroup = new THREE.Group();
        apeirogonGroup.position.set(0, 15, -60);
        scene.add(apeirogonGroup);

        // 1. The Core (Infinite Facets representation via high-poly sphere)
        const coreGeo = new THREE.SphereGeometry(10, 64, 64);
        const coreMat = new THREE.MeshStandardMaterial({
            color: 0x111111,
            metalness: 0.9,
            roughness: 0.1,
            emissive: modeThemes.Professional.core,
            emissiveIntensity: 0.5
        });
        const core = new THREE.Mesh(coreGeo, coreMat);
        apeirogonGroup.add(core);

        // 2. The Outer Lattice (Geometric complexity)
        const latticeGeo = new THREE.IcosahedronGeometry(14, 2);
        const latticeMat = new THREE.MeshBasicMaterial({
            color: 0xffffff,
            wireframe: true,
            transparent: true,
            opacity: 0.1
        });
        const lattice = new THREE.Mesh(latticeGeo, latticeMat);
        apeirogonGroup.add(lattice);

        // 3. Rotating Rings (The Ecosystem Power)
        const ringGeo = new THREE.TorusGeometry(18, 0.2, 16, 100);
        const ringMat = new THREE.MeshBasicMaterial({ color: modeThemes.Professional.core, transparent: true, opacity: 0.4 });

        const ring1 = new THREE.Mesh(ringGeo, ringMat);
        ring1.rotation.x = Math.PI / 2;
        apeirogonGroup.add(ring1);

        const ring2 = ring1.clone();
        ring2.rotation.x = Math.PI / 2.5;
        ring2.rotation.y = Math.PI / 6;
        apeirogonGroup.add(ring2);

        const ring3 = ring1.clone();
        ring3.rotation.x = Math.PI / 1.8;
        ring3.rotation.y = -Math.PI / 6;
        apeirogonGroup.add(ring3);
    };

    // New Particle System Function
    const createCoreParticles = () => {
        const count = 800;
        const geometry = new THREE.BufferGeometry();
        const positions = new Float32Array(count * 3);
        particleVelocities = new Float32Array(count * 3);

        for (let i = 0; i < count; i++) {
            // Start at the center (0,0,0 relative to apeirogonGroup)
            positions[i * 3] = (Math.random() - 0.5) * 2;
            positions[i * 3 + 1] = (Math.random() - 0.5) * 2;
            positions[i * 3 + 2] = (Math.random() - 0.5) * 2;

            // Random direction
            const direction = new THREE.Vector3(
                Math.random() - 0.5,
                Math.random() - 0.5,
                Math.random() - 0.5
            ).normalize();

            // Store velocity
            const speed = 0.05 + Math.random() * 0.15;
            particleVelocities[i * 3] = direction.x * speed;
            particleVelocities[i * 3 + 1] = direction.y * speed;
            particleVelocities[i * 3 + 2] = direction.z * speed;
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        // Use a simple sprite or point
        const sprite = new THREE.TextureLoader().load('https://threejs.org/examples/textures/sprites/spark1.png');

        const material = new THREE.PointsMaterial({
            color: modeThemes.Professional.core,
            size: 1.2,
            map: sprite,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            transparent: true,
            opacity: 0.6
        });

        coreParticles = new THREE.Points(geometry, material);
        apeirogonGroup.add(coreParticles); // Attach to the central group
    };

    const createMolecules = () => {
        // Instanced mesh for small particles orbiting the Apeirogon
        const geometry = new THREE.OctahedronGeometry(0.5, 0);
        const material = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            emissive: 0xffffff,
            emissiveIntensity: 0.5,
            transparent: true,
            opacity: 0.6 
        });
        molecules = new THREE.InstancedMesh(geometry, material, MOLECULE_COUNT);

        const dummy = new THREE.Object3D();
        for(let i=0; i<MOLECULE_COUNT; i++) {
            // Distribute in a spherical cloud
            const r = 25 + Math.random() * 20;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);

            dummy.position.set(
                r * Math.sin(phi) * Math.cos(theta),
                15 + r * Math.sin(phi) * Math.sin(theta),
                -60 + r * Math.cos(phi)
            );
            dummy.rotation.set(Math.random()*Math.PI, Math.random()*Math.PI, 0);
            dummy.scale.setScalar(0.5 + Math.random());
            dummy.updateMatrix();
            molecules.setMatrixAt(i, dummy.matrix);
        }
        scene.add(molecules);
    };

    const createRobot = (path: THREE.CatmullRomCurve3, startProgress: number) => {
        const group = new THREE.Group();

        // --- IMPROVED BOT CLARITY & GEOMETRY ---
        // Sleeker, more distinct parts
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x050505, roughness: 0.1, metalness: 1.0 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 3 
        });
        const chromeMat = new THREE.MeshStandardMaterial({
            color: 0xaaaaaa, roughness: 0.0, metalness: 1.0
        });

        // 1. Main Fuselage
        const torso = new THREE.Mesh(new THREE.ConeGeometry(0.8, 3.5, 6), bodyMat);
        torso.rotation.x = Math.PI / 2; 
        group.add(torso);

        // 2. Engine Core (The "Glob" source)
        const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.6, 0.5, 8), chromeMat);
        engine.rotation.x = Math.PI / 2;
        engine.position.z = 1.8;
        group.add(engine);

        const engineGlow = new THREE.Mesh(new THREE.SphereGeometry(0.35), glowMat);
        engineGlow.position.z = 2.0;
        group.add(engineGlow);

        // 3. Distinct Head
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.5, -1.0);
        group.add(headGroup);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.8), chromeMat);
        headGroup.add(head);

        // 4. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.12);
        const leftEye = new THREE.Mesh(eyeGeo, glowMat);
        leftEye.position.set(-0.2, 0, -0.41);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMat);
        rightEye.position.set(0.2, 0, -0.41);
        headGroup.add(rightEye);

        // 5. Wings (Sharper, clearer)
        const wingShape = new THREE.Shape();
        wingShape.moveTo(0, 0);
        wingShape.lineTo(2.5, 1.5);
        wingShape.lineTo(1.5, 2.0);
        wingShape.lineTo(0, 0.5);
        const wingGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.1, bevelEnabled: false });
        const leftWing = new THREE.Mesh(wingGeo, bodyMat);
        leftWing.rotation.x = Math.PI / 2;
        leftWing.rotation.y = 0.2;
        leftWing.position.set(0.2, 0, 0);
        group.add(leftWing);

        const rightWing = new THREE.Mesh(wingGeo, bodyMat);
        rightWing.rotation.x = Math.PI / 2;
        rightWing.rotation.y = Math.PI - 0.2;
        rightWing.rotation.z = Math.PI; // Flip for symmetry
        rightWing.position.set(-0.2, 0, 0);
        group.add(rightWing);

        scene.add(group);

        // --- GLOB TRAIL SETUP ---
        // Instead of a line, we create a series of spheres that follow the bot
        const trailGlobs: THREE.Mesh[] = [];
        const globCount = 15;
        const globMat = new THREE.MeshBasicMaterial({
            color: 0x00ffff,
            transparent: true,
            opacity: 0.6
        });

        for(let i=0; i<globCount; i++) {
            const scale = 1.0 - (i / globCount);
            const glob = new THREE.Mesh(new THREE.SphereGeometry(0.4 * scale), globMat);
            glob.visible = false; // Initially hidden until positioned
            scene.add(glob);
            trailGlobs.push(glob);
        }

        // --- LASER TOOL SETUP ---
        // A long cylinder that can stretch
        const laserGeo = new THREE.CylinderGeometry(0.05, 0.1, 1, 8);
        laserGeo.translate(0, 0.5, 0); // Pivot at bottom
        laserGeo.rotateX(Math.PI / 2); // Point forward along Z
        const laserMat = new THREE.MeshBasicMaterial({
            color: 0x00ffff,
            transparent: true,
            opacity: 0,
            blending: THREE.AdditiveBlending
        });
        const laserMesh = new THREE.Mesh(laserGeo, laserMat);
        group.add(laserMesh); // Attached to robot

        robots.push({
            group,
            headGroup,
            eyesMaterial: glowMat,
            path: path,
            progress: startProgress,
            speed: 0.1,
            trailGlobs,
            laserMesh,
            isFiring: false,
            isInteract: false,
            interactStartTime: 0
        });
    };

    const createYnoAssets = () => {
        const textureLoader = new THREE.TextureLoader();
        textureLoader.setCrossOrigin('anonymous');
        const ynoTexture = textureLoader.load('https://i.ibb.co/L5k5r6B/yno-coin-logo.png', () => {
            const logoMaterial = new THREE.MeshBasicMaterial({
                map: ynoTexture,
                transparent: true,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
                side: THREE.DoubleSide
            });
            const logoGeometry = new THREE.PlaneGeometry(8, 11.75); 
            ynoLogoPlane = new THREE.Mesh(logoGeometry, logoMaterial);
            ynoLogoPlane.scale.set(0.6, 0.6, 0.6); // Slightly bigger
            ynoLogoPlane.position.set(0, 25, -60); // Above the Apeirogon
            scene.add(ynoLogoPlane);
        });
    };

    const animate = () => {
        animationId = requestAnimationFrame(animate);
        const delta = clock.getDelta();
        const time = clock.getElapsedTime();
        const { emotionalMode: currentMode } = stateRef.current;

        // Audio Analysis
        let currentVolume = 0;
        if (analyser.current) {
            analyser.current.getByteFrequencyData(dataArray);
            currentVolume = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
        }
        const audioInfluence = Math.min(currentVolume / 80, 1.0); // Normalized 0-1

        // Mode Switching Colors
        const theme = modeThemes[currentMode];
        if (theme) {
            if (scene.fog) {
                const currentFog = scene.fog as THREE.FogExp2;
                currentFog.color.setHex(theme.sky);
                currentFog.density += (theme.sky === 0x1a0a00 ? 0.01 : 0.015 - currentFog.density) * 0.05;
            }
            scene.background = new THREE.Color(theme.sky);

            if (terrain1.material) (terrain1.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);
            if (terrain2.material) (terrain2.material as THREE.MeshStandardMaterial).emissive.setHex(theme.grid);

            // Apeirogon Theme
            if (apeirogonGroup) {
                const core = apeirogonGroup.children[0] as THREE.Mesh;
                if (core.material) (core.material as THREE.MeshStandardMaterial).emissive.setHex(theme.core);
                const rings = apeirogonGroup.children.slice(2);
                rings.forEach(r => (r as THREE.Mesh).material && ((r as THREE.Mesh).material as THREE.MeshBasicMaterial).color.setHex(theme.core));
            }

            // Update Particle Colors
            if (coreParticles) {
                (coreParticles.material as THREE.PointsMaterial).color.setHex(theme.core);
            }

            robots.forEach(r => {
                r.eyesMaterial.color.setHex(theme.robot);
                r.eyesMaterial.emissive.setHex(theme.robot);
                r.trailGlobs.forEach(g => (g.material as THREE.MeshBasicMaterial).color.setHex(theme.robot));
                (r.laserMesh.material as THREE.MeshBasicMaterial).color.setHex(theme.laser);
            });
        }

        const speedFactor = (currentMode === 'Enthusiastic' ? 1.5 : currentMode === 'Zen' ? 0.5 : 1) * (1 + audioInfluence * 0.5);

        // --- ANIMATION: PARTICLES ---
        if (coreParticles && particleVelocities) {
            const positions = coreParticles.geometry.attributes.position.array as Float32Array;
            const count = positions.length / 3;
            // Particles move faster with audio
            const particleSpeed = speedFactor * (1 + audioInfluence * 4);

            for (let i = 0; i < count; i++) {
                positions[i * 3] += particleVelocities[i * 3] * particleSpeed;
                positions[i * 3 + 1] += particleVelocities[i * 3 + 1] * particleSpeed;
                positions[i * 3 + 2] += particleVelocities[i * 3 + 2] * particleSpeed;

                // Reset logic: If far from center, reset to roughly center
                const dSq = positions[i * 3]**2 + positions[i * 3 + 1]**2 + positions[i * 3 + 2]**2;
                if (dSq > 1600) { // Radius 40 squared
                    positions[i * 3] = (Math.random() - 0.5) * 2;
                    positions[i * 3 + 1] = (Math.random() - 0.5) * 2;
                    positions[i * 3 + 2] = (Math.random() - 0.5) * 2;
                }
            }
            coreParticles.geometry.attributes.position.needsUpdate = true;
        }

        // --- ANIMATION: TERRAIN SCROLL ---
        const terrainSpeed = 10 * delta * speedFactor;
        if (terrain1 && terrain2) {
            terrain1.position.z += terrainSpeed;
            terrain2.position.z += terrainSpeed;

            if (terrain1.position.z > 50) terrain1.position.z = -550;
            if (terrain2.position.z > 50) terrain2.position.z = -550;
        }

        // --- ANIMATION: LOGO (Pulse and Float) ---
        if (ynoLogoPlane) {
            ynoLogoPlane.position.y = 25 + Math.sin(time * 0.5) * 2;
            const scaleBase = 0.6;
            const scaleAudio = audioInfluence * 0.2;
            const finalScale = scaleBase + scaleAudio + Math.sin(time * 2) * 0.05;
            ynoLogoPlane.scale.set(finalScale, finalScale, finalScale);
            ynoLogoPlane.rotation.y = Math.sin(time * 0.2) * 0.1;
        }

        // --- ANIMATION: APEIROGON (Infinite Sides) ---
        if (apeirogonGroup) {
            // Complex rotation
            apeirogonGroup.rotation.y += 0.005 * speedFactor;

            // Pulse the core based on audio
            const core = apeirogonGroup.children[0] as THREE.Mesh;
            const pulse = 1 + audioInfluence * 0.5;
            core.scale.setScalar(pulse);

            // Rings spin
            apeirogonGroup.children[2].rotation.z += 0.02 * speedFactor;
            apeirogonGroup.children[3].rotation.x += 0.02 * speedFactor;
        }

        // --- ANIMATION: MOLECULES ---
        if (molecules) {
            molecules.rotation.y -= 0.01 * speedFactor;
            molecules.rotation.z = Math.sin(time * 0.2) * 0.1;
        }

        // --- ANIMATION: ROBOTS ---
        robots.forEach(robot => {
            // Path Movement
            const step = (robot.speed * delta * speedFactor);
            robot.progress += step;
            if (robot.progress > 1) robot.progress = 0;

            const currentPos = robot.path.getPoint(robot.progress);
            const lookAtProgress = (robot.progress + 0.02) % 1;
            const lookAtPos = robot.path.getPoint(lookAtProgress);

            robot.group.position.copy(currentPos);
            robot.group.lookAt(lookAtPos);

            // Banking
            const tangent = new THREE.Vector3().subVectors(lookAtPos, currentPos).normalize();
            const roll = -tangent.x * 2.0; 
            robot.group.rotation.z = roll;

            // --- GLOB TRAILS ---
            // Update glob positions: Each glob lerps to the one before it
            const engineWorldPos = new THREE.Vector3(0, 0, 2.0);
            engineWorldPos.applyMatrix4(robot.group.matrixWorld);

            // The first glob follows the engine directly
            if (robot.trailGlobs.length > 0) {
                robot.trailGlobs[0].visible = true;
                robot.trailGlobs[0].position.lerp(engineWorldPos, 0.5);

                for(let i=1; i < robot.trailGlobs.length; i++) {
                    const prevGlob = robot.trailGlobs[i-1];
                    const currGlob = robot.trailGlobs[i];
                    currGlob.visible = true;
                    // Follow previous glob
                    currGlob.position.lerp(prevGlob.position, 0.4); 
                }
            }

            // --- LASER TOOL ALGO ---
            // Fire when audio is high ("Power of the Ecosystem")
            const shouldFire = audioInfluence > 0.6; // Threshold for laser

            if (shouldFire) {
                // Calculate distance and direction to Apeirogon Core
                const corePos = apeirogonGroup.position.clone();
                // We need the laser to point from the robot (local origin) to the core (world pos)
                // Since laser is child of robot, we need corePos in robot's local space
                const coreLocal = corePos.clone().applyMatrix4(robot.group.matrixWorld.clone().invert());

                // Point laser at local core coord
                robot.laserMesh.lookAt(coreLocal);

                // Scale length to distance
                const dist = robot.group.position.distanceTo(corePos);
                robot.laserMesh.scale.z = dist; // Stretch cylinder along Z

                (robot.laserMesh.material as THREE.MeshBasicMaterial).opacity = 0.5 + Math.random() * 0.5;
            } else {
                (robot.laserMesh.material as THREE.MeshBasicMaterial).opacity = 0;
            }

            // Interaction
            if (robot.isInteract) {
                const elapsed = time - robot.interactStartTime;
                if (elapsed < 1.0) {
                    robot.group.rotateZ(0.2);
                    robot.group.scale.setScalar(1.5);
                } else {
                    robot.isInteract = false;
                    robot.group.scale.setScalar(1);
                }
            }

            // Head tracking mouse slightly
            robot.headGroup.rotation.y = mouse.x * 0.5;
            robot.headGroup.rotation.x = -mouse.y * 0.5;
        });

        // Camera Sway
        camera.position.x += (mouse.x * 3 - camera.position.x) * 0.02;
        camera.position.y += (5 + (-mouse.y * 2) - camera.position.y) * 0.02;
        camera.lookAt(0, 5, -60);

        renderer.render(scene, camera);
    };

    const onWindowResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const onDocumentMouseMove = (event: MouseEvent) => {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    };

    const onMouseClick = (event: MouseEvent) => {
        if (event.target !== renderer.domElement) return;

        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);

        const robotGroups = robots.map(r => r.group);
        const intersects = raycaster.intersectObjects(robotGroups, true);

        if (intersects.length > 0) {
            let hitObject: THREE.Object3D | null = intersects[0].object;
            let targetRobot: Robot | undefined;

            while (hitObject) {
                targetRobot = robots.find(r => r.group === hitObject);
                if (targetRobot) break;
                hitObject = hitObject.parent;
            }

            if (targetRobot && !targetRobot.isInteract) {
                targetRobot.isInteract = true;
                targetRobot.interactStartTime = clock.getElapsedTime();
                playInteractionSound();
            }
        }
    };

    init();
    animate();

    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onDocumentMouseMove);
    window.addEventListener('click', onMouseClick);

    return () => {
        cancelAnimationFrame(animationId);
        window.removeEventListener('resize', onWindowResize);
        document.removeEventListener('mousemove', onDocumentMouseMove);
        window.removeEventListener('click', onMouseClick);
        if (mountRef.current && renderer.domElement) {
           mountRef.current.removeChild(renderer.domElement);
        }
    };
  }, [videoRef]);

  return <div ref={mountRef} className="fixed top-0 left-0 w-full h-full z-0" />;
};

