const App: React.FC = () => {
  const [isAudioReady, setIsAudioReady] = useState(false);
  const [showMessageBox, setShowMessageBox] = useState(true);
  const [transcriptionHistory, setTranscriptionHistory] = useState<ChatMessage[]>([]);
  const [isSessionActive, setIsSessionActive] = useState(false);
  const [sessionStatus, setSessionStatus] = useState<'idle' | 'connecting' | 'active' | 'error'>('idle');
  const [audioError, setAudioError] = useState<React.ReactNode | null>(null);
  const [micPermissionStatus, setMicPermissionStatus] = useState<'prompt' | 'granted' | 'denied' | 'unknown'>('unknown');
  const [emotionalMode, setEmotionalMode] = useState<EmotionalMode>('Professional');

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const sessionErrorOccurred = useRef(false);

  const backgroundMusicRef = useRef<HTMLAudioElement | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
  const transcriptionContainerRef = useRef<HTMLDivElement>(null);

  const backgroundGradient = 'radial-gradient(ellipse at center, #1a051a 0%, #03051a 50%, #000000 100%)';

  useEffect(() => {
    transcriptionContainerRef.current?.scrollTo(0, transcriptionContainerRef.current.scrollHeight);
  }, [transcriptionHistory]);

  useEffect(() => {
    const checkMicPermission = async () => {
        if (!navigator.permissions) {
            console.warn('Permissions API not supported.');
            return;
        }
        try {
            const permissionStatus = await navigator.permissions.query({ name: 'microphone' as PermissionName });
            setMicPermissionStatus(permissionStatus.state);
            if (permissionStatus.state === 'denied') {
                setAudioError(PermissionDeniedMessage);
            }
            permissionStatus.onchange = () => {
                setMicPermissionStatus(permissionStatus.state);
                 if (permissionStatus.state === 'denied') {
                    setAudioError(PermissionDeniedMessage);
                } else {
                    setAudioError(null);
                }
            };
        } catch (error) {
            console.error("Could not query microphone permission:", error);
        }
    };
    checkMicPermission();
  }, []); // PermissionDeniedMessage is now constant, safe to remove or keep empty dep array

  const endConversation = useCallback(() => {
    sessionPromiseRef.current?.then(session => session.close());
  }, []);

  const startConversation = useCallback(() => {
    if (sessionPromiseRef.current) return;

    sessionErrorOccurred.current = false;
    setSessionStatus('connecting');
    setTranscriptionHistory([{ speaker: 'System', text: `Connecting to YNO [${emotionalMode} Mode]...` }]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      let nextStartTime = 0;
      const sources = new Set<AudioBufferSourceNode>();
      let currentInputTranscription = '';
      let currentOutputTranscription = '';

      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsSessionActive(true);
            setSessionStatus('active');
            setTranscriptionHistory(prev => [...prev, { speaker: 'System', text: 'Connection established. You may speak.' }]);

            if (!inputAudioContextRef.current) return;
            const source = mediaStreamSourceRef.current;
            if (!source) {
                console.error("Media stream source not available.");
                setSessionStatus('error');
                setTranscriptionHistory(prev => [...prev, { speaker: 'System', text: 'Error: Could not access microphone source.'}]);
                return;
            }

            const scriptProcessor = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
              const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromiseRef.current?.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscription += message.serverContent.outputTranscription.text;
            } else if (message.serverContent?.inputTranscription) {
              currentInputTranscription += message.serverContent.inputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const fullInput = currentInputTranscription.trim();
              if (fullInput) {
                setTranscriptionHistory(prev => [...prev, { speaker: 'User', text: fullInput }]);
              }

              const fullOutput = currentOutputTranscription.trim();
              if (fullOutput) {
                const speaker: Speaker = 'YNO';
                const text = fullOutput.replace(/^YNO:\s*/i, '').trim();
                setTranscriptionHistory(prev => [...prev, { speaker, text }]);
              }

              currentInputTranscription = '';
              currentOutputTranscription = '';
            }

            const base64EncodedAudioString = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64EncodedAudioString && outputAudioContextRef.current) {
              nextStartTime = Math.max(nextStartTime, outputAudioContextRef.current.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64EncodedAudioString), outputAudioContextRef.current, 24000, 1);
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContextRef.current.destination);
              source.addEventListener('ended', () => sources.delete(source));
              source.start(nextStartTime);
              nextStartTime += audioBuffer.duration;
              sources.add(source);
            }

            if (message.serverContent?.interrupted) {
              sources.forEach(source => source.stop());
              sources.clear();
              nextStartTime = 0;
            }
          },
          onerror: (e: ErrorEvent) => {
            console.error('Session error:', e);
            sessionErrorOccurred.current = true;
            setSessionStatus('error');
            setTranscriptionHistory(prev => [...prev, { speaker: 'System', text: "An error occurred with the AI session. The connection has been closed. Please check your network and try starting a new conversation." }]);
          },
          onclose: (e: CloseEvent) => {
            console.log('Session closed');
            scriptProcessorRef.current?.disconnect();
            // Do not disconnect media stream source to keep analyser working for visualizer
            // mediaStreamSourceRef.current?.disconnect(); 
            sessionPromiseRef.current = null;
            setIsSessionActive(false);

            if (!sessionErrorOccurred.current) {
                setSessionStatus('idle');
                setTranscriptionHistory(prev => [...prev, { speaker: 'System', text: 'Conversation ended.' }]);
            }
          },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: systemInstructions[emotionalMode],
        },
      });
    } catch (error) {
        console.error("AI Initialization failed:", error);
        setTranscriptionHistory(prev => [...prev, {speaker: 'System', text: 'Error: Could not initialize AI model.'}]);
        setSessionStatus('error');
    }
  }, [emotionalMode]);

  const initBaseAudio = useCallback(async () => {
    if (isAudioReady || inputAudioContextRef.current) return; // Prevent double initialization
    setAudioError(null);
    try {
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const analyser = inputAudioContextRef.current.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const microphoneSource = inputAudioContextRef.current.createMediaStreamSource(stream);
      mediaStreamSourceRef.current = microphoneSource;
      microphoneSource.connect(analyser);

      if (backgroundMusicRef.current) {
        const musicSource = inputAudioContextRef.current.createMediaElementSource(backgroundMusicRef.current);
        musicSource.connect(analyser);
        musicSource.connect(inputAudioContextRef.current.destination);
      }

      setIsAudioReady(true);
      setShowMessageBox(false);
      videoRef.current?.play().catch(e => console.warn("Video play failed", e));
      backgroundMusicRef.current?.play().catch(e => console.warn("Audio play failed", e));

      // Animation loop moved to ThreeCanvas to avoid React re-renders

    } catch (error) {
      console.error("Audio initialization failed:", error);
      if (error instanceof Error) {
        if (error.name === 'NotAllowedError' || error.message.includes('Permission denied')) {
             setAudioError(PermissionDeniedMessage);
             setMicPermissionStatus('denied');
        } else if (error.name === 'NotFoundError') {
            setAudioError("No microphone was found. Please connect a microphone and try again.");
        }
        else {
            setAudioError(`An unexpected error occurred: ${error.message}. Please try again.`);
        }
    } else {
        setAudioError("An unknown error occurred during audio initialization.");
    }
    }
  }, [isAudioReady]);

  useEffect(() => {
    return () => {
      endConversation();
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
    };
  }, [endConversation]);

  const disabledTooltip = isSessionActive ? "Change mode after session ends" : "";

  return (
    <div style={{ background: backgroundGradient }} className="min-h-screen text-white transition-all duration-500 ease-in-out">
      <ThreeCanvas analyser={analyserRef} videoRef={videoRef} emotionalMode={emotionalMode} />

      <div className="fixed top-0 left-0 w-full h-full z-10 pointer-events-none p-5 md:p-10">
        <header className="absolute top-0 left-0 right-0 h-28 bg-black/30 backdrop-blur-md border-b-2 border-purple-500/50 flex items-center justify-between px-5 md:px-10">
          <h1 className="text-2xl md:text-4xl font-black" style={{ background: `linear-gradient(45deg, ${cosmicColors.cyan}, ${cosmicColors.pink}, ${cosmicColors.purple})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
            YNO.COIN
          </h1>
          <div className="grid grid-cols-4 gap-4 md:gap-6 items-center">
            <StatusModule label="Secure" color={cosmicColors.green} pulse={false} />
            <StatusModule label="Network" color={isSessionActive ? cosmicColors.purple : cosmicColors.green} pulse={isSessionActive} />
            <StatusModule label="Audio" color={isAudioReady ? cosmicColors.purple : cosmicColors.dangerRed} />
            <div className="flex flex-col items-center gap-1 pointer-events-auto">
                <div className="text-xs font-bold uppercase tracking-wider text-gray-400">AI Mode</div>
