                    <ModeButton onClick={() => setEmotionalMode('Professional')} isActive={emotionalMode === 'Professional'} disabled={isSessionActive} color={cosmicColors.cyan} title={disabledTooltip}>Pro</ModeButton>
                    <ModeButton onClick={() => setEmotionalMode('Enthusiastic')} isActive={emotionalMode === 'Enthusiastic'} disabled={isSessionActive} color={cosmicColors.gold} title={disabledTooltip}>Upbeat</ModeButton>
                    <ModeButton onClick={() => setEmotionalMode('Cautious')} isActive={emotionalMode === 'Cautious'} disabled={isSessionActive} color={cosmicColors.green} title={disabledTooltip}>Wary</ModeButton>
                    <ModeButton onClick={() => setEmotionalMode('Zen')} isActive={emotionalMode === 'Zen'} disabled={isSessionActive} color={cosmicColors.pink} title={disabledTooltip}>Calm</ModeButton>
                </div>
            </div>
          </div>
        </header>
      </div>

      <div className="absolute bottom-0 left-0 right-0 p-5 z-20 pointer-events-none flex flex-col items-center">
        <div className="mb-4 pointer-events-auto">
           <CosmicButton onClick={isSessionActive ? endConversation : startConversation} disabled={!isAudioReady || sessionStatus === 'connecting'} variant={isSessionActive ? 'danger' : undefined}>
                {sessionStatus === 'connecting' ? 'Connecting...' : isSessionActive ? 'End Session' : 'Start Session'}
            </CosmicButton>
        </div>
        <div ref={transcriptionContainerRef} className="max-w-4xl w-full mx-auto bg-black/50 backdrop-blur-md rounded-xl p-4 h-48 overflow-y-auto space-y-3 pointer-events-auto font-space-mono text-sm scroll-smooth">
            {transcriptionHistory.map((msg, index) => (
                <div key={index} className={`flex items-start gap-3 ${msg.speaker === 'User' ? 'justify-end' : ''}`}>
                  {msg.speaker !== 'User' && msg.speaker !== 'System' && <div className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center font-bold text-black text-xs bg-purple-400`}>{msg.speaker.charAt(0)}</div>}
                  <div className={`max-w-xl ${msg.speaker === 'User' ? 'text-right' : ''} ${msg.speaker === 'System' ? 'text-center w-full text-gray-400 italic' : ''}`}>
                    {msg.speaker !== 'System' && <span className={`font-bold ${msg.speaker === 'User' ? 'text-cyan-400' : 'text-purple-300'}`}>{msg.speaker === 'User' ? 'You' : msg.speaker}</span>}
                    <p>{msg.text}</p>
                  </div>
                </div>
            ))}
        </div>
      </div>

        {showMessageBox && (
            <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center pointer-events-auto">
                <div className={`max-w-lg w-full p-10 bg-black/80 backdrop-blur-xl border-4 border-[${cosmicColors.purple}] rounded-3xl text-center shadow-[0_0_50px_rgba(138,43,226,0.5)]`}>
                    <h2 className="text-3xl font-black mb-4 uppercase" style={{ background: `linear-gradient(45deg, ${cosmicColors.cyan}, ${cosmicColors.pink})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Welcome to YNO.COIN</h2>
                    <p className="mb-6 opacity-90">Initialize the digital ecosystem. Allow microphone access to have a voice conversation with our AI financial advisor, YNO.</p>
